// Class 11 Physics Unit II: Kinematics (Motion in a Straight Line & Motion in a Plane)
// High-Level Reference Book Content & NCERT Solutions (8 Self-Contained 3D Volumetric SVG Diagrams)

export const c11Phy2HtmlOverview = "\n<style>\n  p, li, div:not(.table-container):not(.table-responsive):not(.pt-scroll-wrapper):not(.mcq-option) {\n    text-align: justify !important;\n  }\n  h1, h2, h3, h4, h5, h6 { text-align: left; }\n  .text-center { text-align: center !important; }\n  .text-left { text-align: left !important; }\n</style>\n\n<div style=\"padding: 12px; color: #E0E0E0; text-align: justify; font-family: system-ui, -apple-system, sans-serif; line-height: 1.7; font-size: 16px;\">\n  <!-- QUICK GLOSSARY & BASIC DEFINITIONS -->\n  <div style=\"background: rgba(142, 45, 226, 0.05); border: 1.5px solid #8E2DE2; border-radius: 12px; padding: 16px; margin-bottom: 25px;\">\n    <h2 class=\"text-center\" style=\"color: #8E2DE2; margin: 0 0 6px 0; font-size: 20px; font-weight: bold; text-align: center !important;\">📖 Quick Glossary & Basic Definitions</h2>\n    <p class=\"text-center\" style=\"color: #8E2DE2; margin: 0 0 16px 0; font-size: 14.5px; text-align: center !important;\">Key Fundamental Terms & Concepts for Unit II: Kinematics (Motion in a Straight Line & Motion in a Plane)</p>\n\n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 10px;\">\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #8E2DE2; border-radius: 6px;\">\n        <b style='color: #8E2DE2; display: block; margin-bottom: 3px;'>1. Kinematics:</b>\n        <span style=\"color: #FFFFFF;\">The branch of mechanics that describes the motion of objects without considering the forces causing the motion.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #8E2DE2; border-radius: 6px;\">\n        <b style='color: #8E2DE2; display: block; margin-bottom: 3px;'>2. Frame of Reference:</b>\n        <span style=\"color: #FFFFFF;\">A coordinate system combined with a clock relative to which the position, velocity, and acceleration of an object are measured.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #8E2DE2; border-radius: 6px;\">\n        <b style='color: #8E2DE2; display: block; margin-bottom: 3px;'>3. Distance vs Displacement:</b>\n        <span style=\"color: #FFFFFF;\">Distance is total path length (scalar), whereas Displacement is the shortest straight-line distance from initial to final position (vector).</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #8E2DE2; border-radius: 6px;\">\n        <b style='color: #8E2DE2; display: block; margin-bottom: 3px;'>4. Instantaneous Velocity:</b>\n        <span style=\"color: #FFFFFF;\">The velocity of a body at a specific instant of time, defined as the derivative of position vector v = dx / dt.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #8E2DE2; border-radius: 6px;\">\n        <b style='color: #8E2DE2; display: block; margin-bottom: 3px;'>5. Uniform Acceleration:</b>\n        <span style=\"color: #FFFFFF;\">Motion in which the velocity of an object changes by equal amounts in equal intervals of time.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #8E2DE2; border-radius: 6px;\">\n        <b style='color: #8E2DE2; display: block; margin-bottom: 3px;'>6. Scalar vs Vector:</b>\n        <span style=\"color: #FFFFFF;\">Scalars possess only magnitude (e.g. Mass, Speed), while Vectors possess both magnitude and direction (e.g. Force, Velocity).</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #8E2DE2; border-radius: 6px;\">\n        <b style='color: #8E2DE2; display: block; margin-bottom: 3px;'>7. Unit Vector:</b>\n        <span style=\"color: #FFFFFF;\">A vector of unit magnitude (1) used purely to specify direction in space, defined as â = A / |A|.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #8E2DE2; border-radius: 6px;\">\n        <b style='color: #8E2DE2; display: block; margin-bottom: 3px;'>8. Projectile Motion:</b>\n        <span style=\"color: #FFFFFF;\">Two-dimensional motion of an object projected into air under the sole influence of gravity near Earth's surface.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #8E2DE2; border-radius: 6px;\">\n        <b style='color: #8E2DE2; display: block; margin-bottom: 3px;'>9. Scalar (Dot) Product:</b>\n        <span style=\"color: #FFFFFF;\">Product of magnitudes of two vectors and cosine of angle between them (A · B = |A||B| cos θ).</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #8E2DE2; border-radius: 6px;\">\n        <b style='color: #8E2DE2; display: block; margin-bottom: 3px;'>10. Centripetal Acceleration:</b>\n        <span style=\"color: #FFFFFF;\">Inward radial acceleration directed towards the center in uniform circular motion, a<sub>c</sub> = v<sup>2</sup> / r = r ω<sup>2</sup>.</span>\n      </div>\n    </div>\n  </div>\n\n  <!-- PART A: MOTION IN A STRAIGHT LINE -->\n  <h1 style=\"color: #8E2DE2; border-bottom: 2.5px solid #8E2DE2; padding-bottom: 6px; margin-top: 25px;\">PART A: MOTION IN A STRAIGHT LINE</h1>\n\n  <!-- SECTION 1 -->\n  <h2 style=\"color: #8E2DE2; border-bottom: 2px solid #8E2DE2; padding-bottom: 6px; margin-top: 20px;\">1. Frame of Reference & Motion in a Straight Line</h2>\n  \n  <div style=\"background: rgba(142, 45, 226, 0.06); border-left: 4px solid #8E2DE2; border-radius: 6px; padding: 12px 16px; margin: 15px 0;\">\n    <b style=\"color: #8E2DE2; font-size: 16.5px; display: block; margin-bottom: 4px;\">📌 Definition (Frame of Reference):</b>\n    <p style=\"margin: 0; color: #FFFFFF; line-height: 1.6; font-size: 15.5px;\">A coordinate system (usually Cartesian x, y, z axes) along with a time-measuring clock attached to an observer, relative to which the motion of a physical body is observed and described.</p>\n  </div>\n  <p>Motion is a relative concept; an object at rest in one frame of reference may be moving relative to another.</p>\n  <div style=\"margin: 12px 0;\">\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #8E2DE2; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Inertial Frame of Reference:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">A frame of reference that is either at rest or moving with a uniform constant velocity (zero acceleration).</span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #8E2DE2; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Non-Inertial Frame of Reference:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">An accelerating or rotating frame of reference relative to an inertial frame.</span>\n  </div>\n  </div>\n\n  <h3 style=\"color: #8E2DE2; margin-top: 20px;\">(ii) Position, Distance, and Displacement</h3>\n  <div style=\"margin: 12px 0;\">\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #8E2DE2; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Distance (Scalar):</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">The total length of the actual path traversed by an object during a given time interval.</span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #8E2DE2; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Displacement (Vector):</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">The shortest directed straight-line distance from initial to final position: Δx = x<sub>2</sub> - x<sub>1</sub>.</span>\n  </div>\n  </div>\n\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(142, 45, 226, 0.35); border-radius: 8px; padding: 10px 14px; text-align: center; margin: 14px 0; font-size: 15.5px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>|Displacement| ≤ Total Distance</b> &nbsp; (Equality holds only for unidirectional straight-line motion)</div>\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #8E2DE2; border-radius: 16px; padding: 16px; margin: 24px 0; box-shadow: 0 10px 30px rgba(142, 45, 226, 0.25);\">\n    <div style=\"color: #8E2DE2; font-weight: bold; font-size: 17px; margin-bottom: 12px; text-align: center; letter-spacing: 0.5px;\">\n      📍 Distance vs Displacement in 1D Rectilinear Motion\n    </div>\n    <div style=\"width: 100%; max-width: 840px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.08);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 480\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <defs>\n    <linearGradient id=\"purpleGrad1\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#8E2DE2\"/>\n      <stop offset=\"100%\" stop-color=\"#4A00E0\"/>\n    </linearGradient>\n    <filter id=\"glowPurple1\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feGaussianBlur stdDeviation=\"5\" result=\"blur\"/>\n      <feComposite in=\"SourceGraphic\" in2=\"blur\" operator=\"over\"/>\n    </filter>\n    <marker id=\"arrowCyan1\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"4\" orient=\"auto\">\n      <path d=\"M0,0 L8,4 L0,8 Z\" fill=\"#00E5FF\"/>\n    </marker>\n    <marker id=\"arrowGreen1\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"4\" orient=\"auto\">\n      <path d=\"M0,0 L8,4 L0,8 Z\" fill=\"#76FF03\"/>\n    </marker>\n  </defs>\n\n  <!-- 3D Ground Grid -->\n  <g opacity=\"0.15\" stroke=\"#94A3B8\" stroke-width=\"1\">\n    <line x1=\"60\" y1=\"360\" x2=\"740\" y2=\"360\"/>\n    <line x1=\"120\" y1=\"300\" x2=\"680\" y2=\"300\"/>\n    <line x1=\"60\" y1=\"360\" x2=\"200\" y2=\"200\"/>\n    <line x1=\"740\" y1=\"360\" x2=\"600\" y2=\"200\"/>\n  </g>\n\n  <!-- 1D Linear Track (X Axis) -->\n  <line x1=\"80\" y1=\"300\" x2=\"720\" y2=\"300\" stroke=\"#475569\" stroke-width=\"3\"/>\n  \n  <!-- Scale Positions: Origin O (x=0), Turning Point P (x=+10m), Final Position Q (x=+4m) -->\n  <circle cx=\"120\" cy=\"300\" r=\"7\" fill=\"#FFFFFF\"/>\n  <text x=\"105\" y=\"330\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">O (x=0)</text>\n\n  <circle cx=\"600\" cy=\"300\" r=\"7\" fill=\"#FFD700\"/>\n  <text x=\"580\" y=\"330\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">P (x=+10 m)</text>\n\n  <circle cx=\"312\" cy=\"300\" r=\"7\" fill=\"#76FF03\"/>\n  <text x=\"290\" y=\"330\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">Q (x=+4 m)</text>\n\n  <!-- Forward Path O to P (10 m) -->\n  <path d=\"M 120 270 Q 360 210 600 270\" fill=\"none\" stroke=\"#00E5FF\" stroke-width=\"3.5\" marker-end=\"url(#arrowCyan1)\" filter=\"url(#glowPurple1)\"/>\n  <text x=\"310\" y=\"225\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">Forward Path O → P (+10 m)</text>\n\n  <!-- Return Path P to Q (-6 m) -->\n  <path d=\"M 600 270 Q 456 240 312 270\" fill=\"none\" stroke=\"#FF512F\" stroke-width=\"3\" stroke-dasharray=\"5,4\"/>\n  <text x=\"410\" y=\"245\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">Return Path P → Q (-6 m)</text>\n\n  <!-- Direct Displacement Vector Δx (O to Q) -->\n  <line x1=\"120\" y1=\"160\" x2=\"312\" y2=\"160\" stroke=\"#76FF03\" stroke-width=\"4\" marker-end=\"url(#arrowGreen1)\"/>\n  <text x=\"130\" y=\"145\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"15.5\" font-weight=\"bold\">Displacement Δx = x_final - x_init = +4 m</text>\n\n  <!-- Comparison Formula Panel Top Right (x=430, y=25, width=345, height=105) -->\n  <rect x=\"430\" y=\"25\" width=\"345\" height=\"105\" rx=\"10\" fill=\"rgba(142,45,226,0.18)\" stroke=\"#8E2DE2\" stroke-width=\"1.8\"/>\n  <text x=\"445\" y=\"55\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"15\" font-weight=\"bold\">Distance = |+10| + |-6| = 16 m</text>\n  <text x=\"445\" y=\"80\" fill=\"#76FF03\" font-family=\"monospace\" font-size=\"15\" font-weight=\"bold\">Displacement Δx = +4 m</text>\n  <text x=\"445\" y=\"106\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"13.5\" font-weight=\"bold\">✓ |Displacement| ≤ Total Distance</text>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 12px; line-height: 1.5; font-weight: 500;\">\n      💡 3D Vector track comparing path length vs displacement vector Δx = x₂ - x₁.\n    </div>\n  </div>\n\n  <!-- SECTION 2 -->\n  <h2 style=\"color: #8E2DE2; border-bottom: 2px solid #8E2DE2; padding-bottom: 6px; margin-top: 30px;\">2. Elementary Concepts of Differentiation & Integration in Kinematics</h2>\n  \n  <div style=\"background: rgba(142, 45, 226, 0.06); border-left: 4px solid #8E2DE2; border-radius: 6px; padding: 12px 16px; margin: 15px 0;\">\n    <b style=\"color: #8E2DE2; font-size: 16.5px; display: block; margin-bottom: 4px;\">📌 Definition (Instantaneous Velocity):</b>\n    <p style=\"margin: 0; color: #FFFFFF; line-height: 1.6; font-size: 15.5px;\">The limiting value of average velocity as the time interval Δt approaches zero: v = dx / dt.</p>\n  </div>\n  <div style=\"margin: 12px 0;\">\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #8E2DE2; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Instantaneous Velocity v(t):</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\"><code style=\"font-size: 14px; white-space: nowrap; font-family: monospace; color: #FFFFFF; display: inline-block;\">v(t) = limit (Δt → 0) [ Δx / Δt ] = dx / dt</code></span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #8E2DE2; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Instantaneous Acceleration a(t):</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\"><code style=\"font-size: 14px; white-space: nowrap; font-family: monospace; color: #FFFFFF; display: inline-block;\">a(t) = dv / dt = d<sup>2</sup>x / dt<sup>2</sup> = v (dv / dx)</code></span>\n  </div>\n  </div>\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #8E2DE2; border-radius: 16px; padding: 16px; margin: 24px 0; box-shadow: 0 10px 30px rgba(142, 45, 226, 0.25);\">\n    <div style=\"color: #8E2DE2; font-weight: bold; font-size: 17px; margin-bottom: 12px; text-align: center; letter-spacing: 0.5px;\">\n      📍 Calculus in Kinematics: Derivative Slope & Integral Area\n    </div>\n    <div style=\"width: 100%; max-width: 840px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.08);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 460\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <defs>\n    <linearGradient id=\"areaGrad2\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"rgba(142, 45, 226, 0.4)\"/>\n      <stop offset=\"100%\" stop-color=\"rgba(142, 45, 226, 0.05)\"/>\n    </linearGradient>\n  </defs>\n\n  <!-- Left Half: Position-Time (x-t) Tangent Slope = Velocity v = dx/dt -->\n  <g transform=\"translate(20, 20)\">\n    <text x=\"182\" y=\"30\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"16.5\" font-weight=\"bold\">1. Derivative: Slope = v = dx/dt</text>\n\n    <!-- Axes -->\n    <line x1=\"50\" y1=\"330\" x2=\"330\" y2=\"330\" stroke=\"#475569\" stroke-width=\"2\"/>\n    <line x1=\"50\" y1=\"330\" x2=\"50\" y2=\"60\" stroke=\"#475569\" stroke-width=\"2\"/>\n    <text x=\"340\" y=\"335\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"13\">t</text>\n    <text x=\"45\" y=\"50\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"13\">x</text>\n\n    <!-- Curve x(t) -->\n    <path d=\"M 50 310 Q 180 280 300 100\" fill=\"none\" stroke=\"#00E5FF\" stroke-width=\"3.5\"/>\n\n    <!-- Tangent Line at Point P -->\n    <line x1=\"100\" y1=\"300\" x2=\"280\" y2=\"110\" stroke=\"#FFD700\" stroke-width=\"2.5\" stroke-dasharray=\"6,4\"/>\n    <circle cx=\"190\" cy=\"205\" r=\"6\" fill=\"#FF512F\"/>\n    <text x=\"205\" y=\"200\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">Point P(t, x)</text>\n\n    <!-- Slope Card at Bottom Left -->\n    <rect x=\"25\" y=\"360\" width=\"315\" height=\"50\" rx=\"8\" fill=\"rgba(0,229,255,0.12)\" stroke=\"#00E5FF\" stroke-width=\"1.5\"/>\n    <text x=\"182\" y=\"391\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Slope = tan θ = dx / dt = v</text>\n  </g>\n\n  <!-- Vertical Divider -->\n  <line x1=\"400\" y1=\"40\" x2=\"400\" y2=\"430\" stroke=\"#334155\" stroke-width=\"2\" stroke-dasharray=\"6,6\"/>\n\n  <!-- Right Half: Velocity-Time (v-t) Area = Displacement s = ∫ v dt -->\n  <g transform=\"translate(415, 20)\">\n    <text x=\"182\" y=\"30\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"16.5\" font-weight=\"bold\">2. Integral: Area = Δx = ∫ v dt</text>\n\n    <!-- Axes -->\n    <line x1=\"50\" y1=\"330\" x2=\"330\" y2=\"330\" stroke=\"#475569\" stroke-width=\"2\"/>\n    <line x1=\"50\" y1=\"330\" x2=\"50\" y2=\"60\" stroke=\"#475569\" stroke-width=\"2\"/>\n    <text x=\"340\" y=\"335\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"13\">t</text>\n    <text x=\"45\" y=\"50\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"13\">v</text>\n\n    <!-- Shaded Integral Area under v-t curve -->\n    <path d=\"M 100 330 L 100 240 Q 200 120 280 200 L 280 330 Z\" fill=\"url(#areaGrad2)\" stroke=\"#8E2DE2\" stroke-width=\"2\"/>\n\n    <!-- Boundary lines t1 and t2 -->\n    <line x1=\"100\" y1=\"330\" x2=\"100\" y2=\"240\" stroke=\"#76FF03\" stroke-dasharray=\"3,3\"/>\n    <line x1=\"280\" y1=\"330\" x2=\"280\" y2=\"200\" stroke=\"#76FF03\" stroke-dasharray=\"3,3\"/>\n    <text x=\"95\" y=\"350\" fill=\"#76FF03\" font-family=\"monospace\" font-size=\"13\">t₁</text>\n    <text x=\"275\" y=\"350\" fill=\"#76FF03\" font-family=\"monospace\" font-size=\"13\">t₂</text>\n\n    <!-- Area Card at Bottom Right -->\n    <rect x=\"25\" y=\"360\" width=\"315\" height=\"50\" rx=\"8\" fill=\"rgba(118,255,3,0.12)\" stroke=\"#76FF03\" stroke-width=\"1.5\"/>\n    <text x=\"182\" y=\"391\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"15\" font-weight=\"bold\">Area = ∫ₜ₁ᵗ₂ v dt = Displacement Δx</text>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 12px; line-height: 1.5; font-weight: 500;\">\n      💡 Dual-panel diagram illustrating dx/dt as slope of tangent to x-t curve and ∫v dt as shaded area under v-t curve.\n    </div>\n  </div>\n\n  <!-- SECTION 3 -->\n  <h2 style=\"color: #8E2DE2; border-bottom: 2px solid #8E2DE2; padding-bottom: 6px; margin-top: 30px;\">3. Uniform vs Non-Uniform Motion & Kinematic Graphs</h2>\n  \n  <div style=\"background: rgba(142, 45, 226, 0.06); border-left: 4px solid #8E2DE2; border-radius: 6px; padding: 12px 16px; margin: 15px 0;\">\n    <b style=\"color: #8E2DE2; font-size: 16.5px; display: block; margin-bottom: 4px;\">📌 Definition (Uniform Motion):</b>\n    <p style=\"margin: 0; color: #FFFFFF; line-height: 1.6; font-size: 15.5px;\">Motion in a straight line in which an object covers equal displacements in equal intervals of time.</p>\n  </div>\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #8E2DE2; border-radius: 16px; padding: 16px; margin: 24px 0; box-shadow: 0 10px 30px rgba(142, 45, 226, 0.25);\">\n    <div style=\"color: #8E2DE2; font-weight: bold; font-size: 17px; margin-bottom: 12px; text-align: center; letter-spacing: 0.5px;\">\n      📍 Kinematic Graphs Reference Set (x-t, v-t, a-t Curves)\n    </div>\n    <div style=\"width: 100%; max-width: 840px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.08);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 460\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <!-- Grid 2x2 of Kinematic Graph Cards -->\n  <g transform=\"translate(25, 20)\">\n    <rect x=\"0\" y=\"0\" width=\"365\" height=\"195\" rx=\"12\" fill=\"rgba(255,255,255,0.03)\" stroke=\"#8E2DE2\" stroke-width=\"1.5\"/>\n    <text x=\"182\" y=\"32\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">1. Object at Rest (v = 0, a = 0)</text>\n    <line x1=\"50\" y1=\"160\" x2=\"330\" y2=\"160\" stroke=\"#475569\" stroke-width=\"1.5\"/>\n    <line x1=\"50\" y1=\"160\" x2=\"50\" y2=\"55\" stroke=\"#475569\" stroke-width=\"1.5\"/>\n    <line x1=\"50\" y1=\"95\" x2=\"320\" y2=\"95\" stroke=\"#00E5FF\" stroke-width=\"3\"/>\n    <text x=\"140\" y=\"85\" fill=\"#00E5FF\" font-family=\"monospace\" font-size=\"14\">Position x = Const</text>\n    <text x=\"140\" y=\"130\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"13.5\">Slope = dx/dt = 0</text>\n  </g>\n\n  <g transform=\"translate(410, 20)\">\n    <rect x=\"0\" y=\"0\" width=\"365\" height=\"195\" rx=\"12\" fill=\"rgba(255,255,255,0.03)\" stroke=\"#8E2DE2\" stroke-width=\"1.5\"/>\n    <text x=\"182\" y=\"32\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">2. Uniform Velocity (v = Const, a = 0)</text>\n    <line x1=\"50\" y1=\"160\" x2=\"330\" y2=\"160\" stroke=\"#475569\" stroke-width=\"1.5\"/>\n    <line x1=\"50\" y1=\"160\" x2=\"50\" y2=\"55\" stroke=\"#475569\" stroke-width=\"1.5\"/>\n    <line x1=\"50\" y1=\"150\" x2=\"300\" y2=\"65\" stroke=\"#76FF03\" stroke-width=\"3\"/>\n    <text x=\"130\" y=\"90\" fill=\"#76FF03\" font-family=\"monospace\" font-size=\"14\">x(t) = x₀ + v t</text>\n    <text x=\"130\" y=\"130\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"13.5\">Constant Positive Slope</text>\n  </g>\n\n  <g transform=\"translate(25, 235)\">\n    <rect x=\"0\" y=\"0\" width=\"365\" height=\"195\" rx=\"12\" fill=\"rgba(255,255,255,0.03)\" stroke=\"#8E2DE2\" stroke-width=\"1.5\"/>\n    <text x=\"182\" y=\"32\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">3. Uniform Acceleration (a = Const &gt; 0)</text>\n    <line x1=\"50\" y1=\"160\" x2=\"330\" y2=\"160\" stroke=\"#475569\" stroke-width=\"1.5\"/>\n    <line x1=\"50\" y1=\"160\" x2=\"50\" y2=\"55\" stroke=\"#475569\" stroke-width=\"1.5\"/>\n    <line x1=\"50\" y1=\"140\" x2=\"300\" y2=\"65\" stroke=\"#FFD700\" stroke-width=\"3\"/>\n    <text x=\"130\" y=\"85\" fill=\"#FFD700\" font-family=\"monospace\" font-size=\"14\">v-t Slope = a = Const</text>\n    <text x=\"130\" y=\"130\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"13.5\">x-t curve is Parabolic</text>\n  </g>\n\n  <g transform=\"translate(410, 235)\">\n    <rect x=\"0\" y=\"0\" width=\"365\" height=\"195\" rx=\"12\" fill=\"rgba(255,255,255,0.03)\" stroke=\"#8E2DE2\" stroke-width=\"1.5\"/>\n    <text x=\"182\" y=\"32\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">4. Uniform Retardation (a = - Const)</text>\n    <line x1=\"50\" y1=\"160\" x2=\"330\" y2=\"160\" stroke=\"#475569\" stroke-width=\"1.5\"/>\n    <line x1=\"50\" y1=\"160\" x2=\"50\" y2=\"55\" stroke=\"#475569\" stroke-width=\"1.5\"/>\n    <line x1=\"50\" y1=\"65\" x2=\"300\" y2=\"150\" stroke=\"#FF512F\" stroke-width=\"3\"/>\n    <text x=\"120\" y=\"85\" fill=\"#FF512F\" font-family=\"monospace\" font-size=\"14\">v(t) = u - a t</text>\n    <text x=\"120\" y=\"130\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"13.5\">Negative Slope = Retardation</text>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 12px; line-height: 1.5; font-weight: 500;\">\n      💡 4 3D perspective graph cards comparing Object at Rest, Uniform Velocity, Uniform Acceleration, and Uniform Retardation.\n    </div>\n  </div>\n\n  <!-- SECTION 4 -->\n  <h2 style=\"color: #8E2DE2; border-bottom: 2px solid #8E2DE2; padding-bottom: 6px; margin-top: 30px;\">4. Kinematic Equations for Uniformly Accelerated Motion (Graphical Derivation)</h2>\n  \n  <div style=\"background: rgba(142, 45, 226, 0.06); border-left: 4px solid #8E2DE2; border-radius: 6px; padding: 12px 16px; margin: 15px 0;\">\n    <b style=\"color: #8E2DE2; font-size: 16.5px; display: block; margin-bottom: 4px;\">📌 Definition (Uniformly Accelerated Motion):</b>\n    <p style=\"margin: 0; color: #FFFFFF; line-height: 1.6; font-size: 15.5px;\">Motion along a straight line in which acceleration a remains constant in magnitude and direction.</p>\n  </div>\n  <div style=\"margin: 12px 0;\">\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #8E2DE2; font-size: 15.5px; display: block; margin-bottom: 3px;\">• First Equation of Motion:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\"><code style=\"font-size: 14px; white-space: nowrap; font-family: monospace; color: #FFFFFF; display: inline-block;\">v = u + a t</code></span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #8E2DE2; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Second Equation of Motion:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\"><code style=\"font-size: 14px; white-space: nowrap; font-family: monospace; color: #FFFFFF; display: inline-block;\">s = u t + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> a t<sup>2</sup></code></span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #8E2DE2; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Third Equation of Motion:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\"><code style=\"font-size: 14px; white-space: nowrap; font-family: monospace; color: #FFFFFF; display: inline-block;\">v<sup>2</sup> - u<sup>2</sup> = 2 a s</code></span>\n  </div>\n  </div>\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #8E2DE2; border-radius: 16px; padding: 16px; margin: 24px 0; box-shadow: 0 10px 30px rgba(142, 45, 226, 0.25);\">\n    <div style=\"color: #8E2DE2; font-weight: bold; font-size: 17px; margin-bottom: 12px; text-align: center; letter-spacing: 0.5px;\">\n      📍 Graphical Derivation of Kinematic Equations of Motion\n    </div>\n    <div style=\"width: 100%; max-width: 840px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.08);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 460\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <defs>\n    <linearGradient id=\"rectGrad4\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"rgba(0, 229, 255, 0.3)\"/>\n      <stop offset=\"100%\" stop-color=\"rgba(0, 229, 255, 0.05)\"/>\n    </linearGradient>\n    <linearGradient id=\"triGrad4\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"rgba(118, 255, 3, 0.3)\"/>\n      <stop offset=\"100%\" stop-color=\"rgba(118, 255, 3, 0.05)\"/>\n    </linearGradient>\n  </defs>\n\n  <!-- Left Side: Velocity-Time Graph for Uniform Acceleration -->\n  <g transform=\"translate(30, 20)\">\n    <text x=\"180\" y=\"30\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"16.5\" font-weight=\"bold\">1. Velocity-Time Graph Breakdown</text>\n\n    <!-- Axes -->\n    <line x1=\"60\" y1=\"330\" x2=\"350\" y2=\"330\" stroke=\"#475569\" stroke-width=\"2\"/>\n    <line x1=\"60\" y1=\"330\" x2=\"60\" y2=\"50\" stroke=\"#475569\" stroke-width=\"2\"/>\n    <text x=\"360\" y=\"335\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"13\">Time t</text>\n    <text x=\"50\" y=\"40\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"13\">Velocity v</text>\n\n    <!-- Shaded Rectangle (u · t) -->\n    <rect x=\"60\" y=\"240\" width=\"240\" height=\"90\" fill=\"url(#rectGrad4)\" stroke=\"#00E5FF\" stroke-width=\"1.2\"/>\n    <text x=\"140\" y=\"290\" fill=\"#00E5FF\" font-family=\"monospace\" font-size=\"15\" font-weight=\"bold\">Area₁ = u · t</text>\n\n    <!-- Shaded Triangle (1/2 · a · t²) -->\n    <polygon points=\"60,240 300,240 300,80\" fill=\"url(#triGrad4)\" stroke=\"#76FF03\" stroke-width=\"1.2\"/>\n    <text x=\"180\" y=\"200\" fill=\"#76FF03\" font-family=\"monospace\" font-size=\"15\" font-weight=\"bold\">Area₂ = ½ a t²</text>\n\n    <!-- Points A, B, C, D -->\n    <line x1=\"60\" y1=\"240\" x2=\"300\" y2=\"80\" stroke=\"#FFD700\" stroke-width=\"3.5\"/>\n    <circle cx=\"60\" cy=\"240\" r=\"6\" fill=\"#FF512F\"/>\n    <circle cx=\"300\" cy=\"80\" r=\"6\" fill=\"#FF512F\"/>\n    \n    <text x=\"35\" y=\"245\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">u (A)</text>\n    <text x=\"310\" y=\"75\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">v (B)</text>\n    <text x=\"305\" y=\"245\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"14\">C</text>\n    <text x=\"295\" y=\"350\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"14\">D (t)</text>\n  </g>\n\n  <!-- Right Side: 3 Derivation Cards -->\n  <g transform=\"translate(415, 20)\">\n    <rect x=\"0\" y=\"0\" width=\"360\" height=\"410\" rx=\"12\" fill=\"rgba(15,23,42,0.9)\" stroke=\"#8E2DE2\" stroke-width=\"1.8\"/>\n    <text x=\"180\" y=\"32\" text-anchor=\"middle\" fill=\"#8E2DE2\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">2. Derived Kinematic Equations</text>\n\n    <rect x=\"15\" y=\"55\" width=\"330\" height=\"95\" rx=\"8\" fill=\"rgba(0,229,255,0.1)\" stroke=\"#00E5FF\" stroke-width=\"1.2\"/>\n    <text x=\"180\" y=\"80\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">1st Eq: Slope = a = (v - u) / t</text>\n    <text x=\"180\" y=\"112\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"17\" font-weight=\"bold\">v = u + a t</text>\n\n    <rect x=\"15\" y=\"165\" width=\"330\" height=\"105\" rx=\"8\" fill=\"rgba(118,255,3,0.1)\" stroke=\"#76FF03\" stroke-width=\"1.2\"/>\n    <text x=\"180\" y=\"190\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">2nd Eq: Total Area s = Area₁ + Area₂</text>\n    <text x=\"180\" y=\"222\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"17\" font-weight=\"bold\">s = u t + ½ a t²</text>\n\n    <rect x=\"15\" y=\"285\" width=\"330\" height=\"105\" rx=\"8\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#FFD700\" stroke-width=\"1.2\"/>\n    <text x=\"180\" y=\"310\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">3rd Eq: Trapezoid Area s = ½ (u+v) t</text>\n    <text x=\"180\" y=\"342\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"17\" font-weight=\"bold\">v² - u² = 2 a s</text>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 12px; line-height: 1.5; font-weight: 500;\">\n      💡 3D Velocity-Time graph showing trapezoid area breakdown into rectangle (u·t) and triangle (1/2 a t²).\n    </div>\n  </div>\n\n  <!-- PART B: MOTION IN A PLANE -->\n  <h1 style=\"color: #8E2DE2; border-bottom: 2.5px solid #8E2DE2; padding-bottom: 6px; margin-top: 35px;\">PART B: MOTION IN A PLANE (VECTORS & 2D MOTION)</h1>\n\n  <!-- SECTION 5 -->\n  <h2 style=\"color: #8E2DE2; border-bottom: 2px solid #8E2DE2; padding-bottom: 6px; margin-top: 20px;\">5. Scalars, Vectors & Vector Algebra</h2>\n  \n  <div style=\"background: rgba(142, 45, 226, 0.06); border-left: 4px solid #8E2DE2; border-radius: 6px; padding: 12px 16px; margin: 15px 0;\">\n    <b style=\"color: #8E2DE2; font-size: 16.5px; display: block; margin-bottom: 4px;\">📌 Definition (Vector Quantity):</b>\n    <p style=\"margin: 0; color: #FFFFFF; line-height: 1.6; font-size: 15.5px;\">A physical quantity that possesses both magnitude and direction in space and obeys laws of vector addition.</p>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(142, 45, 226, 0.35); border-radius: 8px; padding: 10px 14px; text-align: center; margin: 14px 0; font-size: 15.5px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>A = A<sub>x</sub> î + A<sub>y</sub> ĵ &nbsp;|&nbsp; |A| = √(A<sub>x</sub><sup>2</sup> + A<sub>y</sub><sup>2</sup>) &nbsp;|&nbsp; tan θ = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">A<sub>y</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">A<sub>x</sub></span>\n  </span></b></div>\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #8E2DE2; border-radius: 16px; padding: 16px; margin: 24px 0; box-shadow: 0 10px 30px rgba(142, 45, 226, 0.25);\">\n    <div style=\"color: #8E2DE2; font-weight: bold; font-size: 17px; margin-bottom: 12px; text-align: center; letter-spacing: 0.5px;\">\n      📍 Resolution of Vector A into Rectangular Components\n    </div>\n    <div style=\"width: 100%; max-width: 840px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.08);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 460\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <defs>\n    <filter id=\"glowVector5\" x=\"-30%\" y=\"-30%\" width=\"160%\" height=\"160%\">\n      <feGaussianBlur stdDeviation=\"6\" result=\"blur\"/>\n      <feComposite in=\"SourceGraphic\" in2=\"blur\" operator=\"over\"/>\n    </filter>\n    <marker id=\"arrowPurple5\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"4\" orient=\"auto\">\n      <path d=\"M0,0 L8,4 L0,8 Z\" fill=\"#8E2DE2\"/>\n    </marker>\n    <marker id=\"arrowCyan5\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"4\" orient=\"auto\">\n      <path d=\"M0,0 L8,4 L0,8 Z\" fill=\"#00E5FF\"/>\n    </marker>\n    <marker id=\"arrowGreen5\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"4\" orient=\"auto\">\n      <path d=\"M0,0 L8,4 L0,8 Z\" fill=\"#76FF03\"/>\n    </marker>\n  </defs>\n\n  <!-- Formula Card TOP-LEFT (x=25, y=25, width=320, height=95) - Completely Clear of All Vectors! -->\n  <rect x=\"25\" y=\"25\" width=\"320\" height=\"95\" rx=\"10\" fill=\"rgba(142,45,226,0.18)\" stroke=\"#8E2DE2\" stroke-width=\"1.8\"/>\n  <text x=\"40\" y=\"52\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"16\" font-weight=\"bold\">|A| = √(A_x² + A_y²)</text>\n  <text x=\"40\" y=\"76\" fill=\"#00E5FF\" font-family=\"monospace\" font-size=\"15\" font-weight=\"bold\">tan θ = A_y / A_x</text>\n  <text x=\"40\" y=\"98\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"13\">• 2D Rectangular Resolution</text>\n\n  <!-- 3D Ground Base Plane -->\n  <polygon points=\"120,380 470,380 670,260 320,260\" fill=\"rgba(148,163,184,0.08)\" stroke=\"#475569\" stroke-width=\"2\"/>\n\n  <!-- Origin O -->\n  <circle cx=\"200\" cy=\"340\" r=\"8\" fill=\"#FFFFFF\"/>\n  <text x=\"165\" y=\"360\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">O (0,0)</text>\n\n  <!-- Vector Ax Component along X Axis -->\n  <line x1=\"200\" y1=\"340\" x2=\"520\" y2=\"340\" stroke=\"#00E5FF\" stroke-width=\"4.5\" marker-end=\"url(#arrowCyan5)\"/>\n  <text x=\"330\" y=\"370\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">A_x = |A| cos θ î</text>\n\n  <!-- Vector Ay Component along Y Axis -->\n  <line x1=\"200\" y1=\"340\" x2=\"200\" y2=\"150\" stroke=\"#76FF03\" stroke-width=\"4.5\" marker-end=\"url(#arrowGreen5)\"/>\n  <text x=\"90\" y=\"240\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">A_y = |A| sin θ ĵ</text>\n\n  <!-- Dotted Rectangle Projection Lines -->\n  <line x1=\"520\" y1=\"340\" x2=\"520\" y2=\"150\" stroke=\"#94A3B8\" stroke-dasharray=\"4,4\" stroke-width=\"2\"/>\n  <line x1=\"200\" y1=\"150\" x2=\"520\" y2=\"150\" stroke=\"#94A3B8\" stroke-dasharray=\"4,4\" stroke-width=\"2\"/>\n\n  <!-- Resultant Vector A (Pointing up-right to 512, 156 with ZERO overlap!) -->\n  <line x1=\"200\" y1=\"340\" x2=\"512\" y2=\"156\" stroke=\"#8E2DE2\" stroke-width=\"5.5\" marker-end=\"url(#arrowPurple5)\" filter=\"url(#glowVector5)\"/>\n  <text x=\"340\" y=\"220\" fill=\"#8E2DE2\" font-family=\"sans-serif\" font-size=\"20\" font-weight=\"bold\">A = A_x î + A_y ĵ</text>\n\n  <!-- Angle θ Arc -->\n  <path d=\"M 270 340 A 70 70 0 0 0 255 295\" fill=\"none\" stroke=\"#FFD700\" stroke-width=\"3\"/>\n  <text x=\"280\" y=\"320\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">θ</text>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 12px; line-height: 1.5; font-weight: 500;\">\n      💡 3D Vector spatial plane showing vector A resolved into Ax = A cos θ along x-axis and Ay = A sin θ along y-axis.\n    </div>\n  </div>\n\n  <!-- SECTION 6 -->\n  <h2 style=\"color: #8E2DE2; border-bottom: 2px solid #8E2DE2; padding-bottom: 6px; margin-top: 30px;\">6. Scalar (Dot) and Vector (Cross) Product of Vectors</h2>\n  \n  <div style=\"background: rgba(142, 45, 226, 0.06); border-left: 4px solid #8E2DE2; border-radius: 6px; padding: 12px 16px; margin: 15px 0;\">\n    <b style=\"color: #8E2DE2; font-size: 16.5px; display: block; margin-bottom: 4px;\">📌 Definition (Scalar Product (A · B)):</b>\n    <p style=\"margin: 0; color: #FFFFFF; line-height: 1.6; font-size: 15.5px;\">The scalar quantity: A · B = |A||B| cos θ.</p>\n  </div>\n  \n  <div style=\"background: rgba(142, 45, 226, 0.06); border-left: 4px solid #8E2DE2; border-radius: 6px; padding: 12px 16px; margin: 15px 0;\">\n    <b style=\"color: #8E2DE2; font-size: 16.5px; display: block; margin-bottom: 4px;\">📌 Definition (Vector Product (A × B)):</b>\n    <p style=\"margin: 0; color: #FFFFFF; line-height: 1.6; font-size: 15.5px;\">The vector quantity: A × B = |A||B| sin θ n̂.</p>\n  </div>\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #8E2DE2; border-radius: 16px; padding: 16px; margin: 24px 0; box-shadow: 0 10px 30px rgba(142, 45, 226, 0.25);\">\n    <div style=\"color: #8E2DE2; font-weight: bold; font-size: 17px; margin-bottom: 12px; text-align: center; letter-spacing: 0.5px;\">\n      📍 3D Vector Multiplication: Dot Product vs Cross Product\n    </div>\n    <div style=\"width: 100%; max-width: 840px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.08);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 500\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <defs>\n    <filter id=\"glowCyan6\" x=\"-30%\" y=\"-30%\" width=\"160%\" height=\"160%\">\n      <feGaussianBlur stdDeviation=\"6\" result=\"blur\"/>\n      <feComposite in=\"SourceGraphic\" in2=\"blur\" operator=\"over\"/>\n    </filter>\n    <marker id=\"arrowGreen6\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"4\" orient=\"auto\">\n      <path d=\"M0,0 L8,4 L0,8 Z\" fill=\"#76FF03\"/>\n    </marker>\n    <marker id=\"arrowPink6\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"4\" orient=\"auto\">\n      <path d=\"M0,0 L8,4 L0,8 Z\" fill=\"#FF512F\"/>\n    </marker>\n  </defs>\n\n  <!-- Left Side: Dot Product (Scalar Output) (Width 365, Center x = 182) -->\n  <g transform=\"translate(20, 20)\">\n    <text x=\"182\" y=\"30\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"16.5\" font-weight=\"bold\">1. Scalar (Dot) Product: A · B</text>\n\n    <!-- Vectors A and B -->\n    <line x1=\"50\" y1=\"280\" x2=\"300\" y2=\"280\" stroke=\"#00E5FF\" stroke-width=\"4\"/>\n    <text x=\"310\" y=\"285\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">A</text>\n\n    <line x1=\"50\" y1=\"280\" x2=\"230\" y2=\"130\" stroke=\"#FFD700\" stroke-width=\"4\"/>\n    <text x=\"240\" y=\"130\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">B</text>\n\n    <!-- Projection B cos θ -->\n    <line x1=\"230\" y1=\"130\" x2=\"230\" y2=\"280\" stroke=\"#76FF03\" stroke-dasharray=\"4,4\" stroke-width=\"2\"/>\n    <line x1=\"50\" y1=\"280\" x2=\"230\" y2=\"280\" stroke=\"#76FF03\" stroke-width=\"5\"/>\n    <text x=\"100\" y=\"310\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">Projection: |B| cos θ</text>\n\n    <!-- Angle θ -->\n    <path d=\"M 110 280 A 60 60 0 0 0 100 240\" fill=\"none\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n    <text x=\"120\" y=\"260\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"15\">θ</text>\n\n    <!-- Extended Bottom Summary Box -->\n    <rect x=\"0\" y=\"360\" width=\"365\" height=\"110\" rx=\"12\" fill=\"rgba(0,229,255,0.12)\" stroke=\"#00E5FF\" stroke-width=\"1.8\"/>\n    <text x=\"182\" y=\"390\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">Scalar Dot Product Law</text>\n    <text x=\"182\" y=\"420\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"15\" font-weight=\"bold\">A · B = |A| |B| cos θ</text>\n    <text x=\"182\" y=\"448\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"monospace\" font-size=\"14\">A · B = A_x B_x + A_y B_y + A_z B_z</text>\n  </g>\n\n  <!-- Vertical Divider -->\n  <line x1=\"400\" y1=\"40\" x2=\"400\" y2=\"470\" stroke=\"#334155\" stroke-width=\"2\" stroke-dasharray=\"6,6\"/>\n\n  <!-- Right Side: Cross Product (Vector Output C = A x B) (Width 365, Center x = 182) -->\n  <g transform=\"translate(415, 20)\">\n    <text x=\"182\" y=\"30\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"16.5\" font-weight=\"bold\">2. Vector (Cross) Product: C = A × B</text>\n\n    <!-- 3D Base Plane -->\n    <polygon points=\"40,290 230,290 330,220 140,220\" fill=\"rgba(148,163,184,0.08)\" stroke=\"#475569\" stroke-width=\"1.5\"/>\n\n    <!-- Pivot O -->\n    <circle cx=\"140\" cy=\"255\" r=\"6\" fill=\"#FFFFFF\"/>\n\n    <!-- Vector A and B in Plane -->\n    <line x1=\"140\" y1=\"255\" x2=\"280\" y2=\"255\" stroke=\"#00E5FF\" stroke-width=\"3.5\"/>\n    <text x=\"290\" y=\"260\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">A</text>\n\n    <line x1=\"140\" y1=\"255\" x2=\"210\" y2=\"185\" stroke=\"#FFD700\" stroke-width=\"3.5\"/>\n    <text x=\"220\" y=\"180\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">B</text>\n\n    <!-- Vertical Cross Product Vector C (Bursting Upward) -->\n    <line x1=\"140\" y1=\"255\" x2=\"140\" y2=\"60\" stroke=\"#76FF03\" stroke-width=\"5\" marker-end=\"url(#arrowGreen6)\" filter=\"url(#glowCyan6)\"/>\n    <text x=\"155\" y=\"75\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">C = A × B</text>\n\n    <!-- Right Hand Rule Spiral -->\n    <path d=\"M 180 240 A 40 20 0 0 0 155 220\" fill=\"none\" stroke=\"#76FF03\" stroke-dasharray=\"3,3\" stroke-width=\"2\"/>\n\n    <!-- Extended Bottom Summary Box -->\n    <rect x=\"0\" y=\"360\" width=\"365\" height=\"110\" rx=\"12\" fill=\"rgba(118,255,3,0.12)\" stroke=\"#76FF03\" stroke-width=\"1.8\"/>\n    <text x=\"182\" y=\"390\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">Vector Cross Product Law</text>\n    <text x=\"182\" y=\"420\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"15\" font-weight=\"bold\">C = A × B = |A| |B| sin θ n̂</text>\n    <text x=\"182\" y=\"448\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"13.5\">|C| = Area of Parallelogram formed by A &amp; B</text>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 12px; line-height: 1.5; font-weight: 500;\">\n      💡 Dual-panel 3D diagram comparing Dot Product projection A · B vs Cross Product C = A × B.\n    </div>\n  </div>\n\n  <!-- SECTION 7 -->\n  <h2 style=\"color: #8E2DE2; border-bottom: 2px solid #8E2DE2; padding-bottom: 6px; margin-top: 30px;\">7. Projectile Motion in a Plane</h2>\n  \n  <div style=\"background: rgba(142, 45, 226, 0.06); border-left: 4px solid #8E2DE2; border-radius: 6px; padding: 12px 16px; margin: 15px 0;\">\n    <b style=\"color: #8E2DE2; font-size: 16.5px; display: block; margin-bottom: 4px;\">📌 Definition (Projectile Motion):</b>\n    <p style=\"margin: 0; color: #FFFFFF; line-height: 1.6; font-size: 15.5px;\">The two-dimensional parabolic motion of a body projected into air under sole influence of gravity.</p>\n  </div>\n  <div style=\"margin: 12px 0;\">\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #8E2DE2; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Time of Flight (T):</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\"><code style=\"font-size: 14px; white-space: nowrap; font-family: monospace; color: #FFFFFF; display: inline-block;\">T = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">2 u sin θ</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">g</span>\n  </span></code></span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #8E2DE2; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Maximum Height (H):</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\"><code style=\"font-size: 14px; white-space: nowrap; font-family: monospace; color: #FFFFFF; display: inline-block;\">H = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">u<sup>2</sup> sin<sup>2</sup> θ</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2 g</span>\n  </span></code></span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #8E2DE2; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Horizontal Range (R):</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\"><code style=\"font-size: 14px; white-space: nowrap; font-family: monospace; color: #FFFFFF; display: inline-block;\">R = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">u<sup>2</sup> sin 2θ</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">g</span>\n  </span></code></span>\n  </div>\n  </div>\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #8E2DE2; border-radius: 16px; padding: 16px; margin: 24px 0; box-shadow: 0 10px 30px rgba(142, 45, 226, 0.25);\">\n    <div style=\"color: #8E2DE2; font-weight: bold; font-size: 17px; margin-bottom: 12px; text-align: center; letter-spacing: 0.5px;\">\n      📍 Parabolic Trajectory of Projectile Motion\n    </div>\n    <div style=\"width: 100%; max-width: 840px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.08);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 480\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <defs>\n    <linearGradient id=\"projGrad7\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" stop-color=\"#8E2DE2\"/>\n      <stop offset=\"50%\" stop-color=\"#00E5FF\"/>\n      <stop offset=\"100%\" stop-color=\"#FF512F\"/>\n    </linearGradient>\n    <filter id=\"glowProj7\" x=\"-30%\" y=\"-30%\" width=\"160%\" height=\"160%\">\n      <feGaussianBlur stdDeviation=\"6\" result=\"blur\"/>\n      <feComposite in=\"SourceGraphic\" in2=\"blur\" operator=\"over\"/>\n    </filter>\n  </defs>\n\n  <polygon points=\"60,380 740,380 660,310 140,310\" fill=\"rgba(148,163,184,0.06)\" stroke=\"#334155\" stroke-width=\"1.5\"/>\n  <text x=\"80\" y=\"405\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"14\">3D Horizontal Ground</text>\n\n  <path d=\"M 100 350 Q 400 330 700 350\" fill=\"none\" stroke=\"rgba(0,0,0,0.6)\" stroke-width=\"6\"/>\n  <path d=\"M 100 350 Q 400 30 700 350\" fill=\"none\" stroke=\"url(#projGrad7)\" stroke-width=\"4.5\" filter=\"url(#glowProj7)\"/>\n\n  <circle cx=\"100\" cy=\"350\" r=\"9\" fill=\"#00E5FF\"/>\n  <text x=\"45\" y=\"365\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">Launch O</text>\n\n  <line x1=\"100\" y1=\"350\" x2=\"220\" y2=\"210\" stroke=\"#76FF03\" stroke-width=\"4\"/>\n  <text x=\"230\" y=\"210\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">Initial Velocity u</text>\n\n  <path d=\"M 160 350 A 60 60 0 0 0 145 300\" fill=\"none\" stroke=\"#FFD700\" stroke-width=\"2.5\"/>\n  <text x=\"165\" y=\"335\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">θ</text>\n\n  <circle cx=\"400\" cy=\"190\" r=\"10\" fill=\"#FFD700\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <text x=\"340\" y=\"145\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">Apex (v_y = 0, v_x = u cos θ)</text>\n\n  <line x1=\"400\" y1=\"190\" x2=\"400\" y2=\"350\" stroke=\"#FF512F\" stroke-width=\"2.5\" stroke-dasharray=\"4,4\"/>\n  <text x=\"410\" y=\"270\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">H_max = u² sin²θ / 2g</text>\n\n  <line x1=\"100\" y1=\"365\" x2=\"700\" y2=\"365\" stroke=\"#00E5FF\" stroke-width=\"2\"/>\n  <line x1=\"100\" y1=\"355\" x2=\"100\" y2=\"375\" stroke=\"#00E5FF\" stroke-width=\"2\"/>\n  <line x1=\"700\" y1=\"355\" x2=\"700\" y2=\"375\" stroke=\"#00E5FF\" stroke-width=\"2\"/>\n  <text x=\"330\" y=\"380\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">Range R = u² sin 2θ / g</text>\n\n  <rect x=\"430\" y=\"25\" width=\"345\" height=\"95\" rx=\"10\" fill=\"rgba(142,45,226,0.18)\" stroke=\"#8E2DE2\" stroke-width=\"1.8\"/>\n  <text x=\"445\" y=\"52\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"15\" font-weight=\"bold\">y = x tan θ - (g x²) / (2 u² cos² θ)</text>\n  <text x=\"445\" y=\"76\" fill=\"#76FF03\" font-family=\"monospace\" font-size=\"15\" font-weight=\"bold\">Time of Flight T = 2 u sin θ / g</text>\n  <text x=\"445\" y=\"98\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"13\">• Parabolic Trajectory Law</text>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 12px; line-height: 1.5; font-weight: 500;\">\n      💡 Complete 3D parabolic trajectory curve showing projection angle θ, maximum height H, range R.\n    </div>\n  </div>\n\n  <!-- SECTION 8 -->\n  <h2 style=\"color: #8E2DE2; border-bottom: 2px solid #8E2DE2; padding-bottom: 6px; margin-top: 30px;\">8. Uniform Circular Motion</h2>\n  \n  <div style=\"background: rgba(142, 45, 226, 0.06); border-left: 4px solid #8E2DE2; border-radius: 6px; padding: 12px 16px; margin: 15px 0;\">\n    <b style=\"color: #8E2DE2; font-size: 16.5px; display: block; margin-bottom: 4px;\">📌 Definition (Uniform Circular Motion):</b>\n    <p style=\"margin: 0; color: #FFFFFF; line-height: 1.6; font-size: 15.5px;\">Motion of a body along a circular path of fixed radius r at constant speed v.</p>\n  </div>\n  <div style=\"margin: 12px 0;\">\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #8E2DE2; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Linear vs Angular Velocity:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\"><code style=\"font-size: 14px; white-space: nowrap; font-family: monospace; color: #FFFFFF; display: inline-block;\">v = r ω</code></span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #8E2DE2; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Centripetal Acceleration (a<sub>c</sub>):</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\"><code style=\"font-size: 14px; white-space: nowrap; font-family: monospace; color: #FFFFFF; display: inline-block;\">a<sub>c</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">v<sup>2</sup></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">r</span>\n  </span> = r ω<sup>2</sup></code></span>\n  </div>\n  </div>\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #8E2DE2; border-radius: 16px; padding: 16px; margin: 24px 0; box-shadow: 0 10px 30px rgba(142, 45, 226, 0.25);\">\n    <div style=\"color: #8E2DE2; font-weight: bold; font-size: 17px; margin-bottom: 12px; text-align: center; letter-spacing: 0.5px;\">\n      📍 Uniform Circular Motion & Centripetal Acceleration Vector\n    </div>\n    <div style=\"width: 100%; max-width: 840px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.08);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 460\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <defs>\n    <radialGradient id=\"circGrad8\" cx=\"40%\" cy=\"40%\" r=\"60%\">\n      <stop offset=\"0%\" stop-color=\"rgba(0, 229, 255, 0.2)\"/>\n      <stop offset=\"100%\" stop-color=\"rgba(142, 45, 226, 0.05)\"/>\n    </radialGradient>\n    <filter id=\"glowCirc8\" x=\"-30%\" y=\"-30%\" width=\"160%\" height=\"160%\">\n      <feGaussianBlur stdDeviation=\"6\" result=\"blur\"/>\n      <feComposite in=\"SourceGraphic\" in2=\"blur\" operator=\"over\"/>\n    </filter>\n    <marker id=\"arrowRed8\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"4\" orient=\"auto\">\n      <path d=\"M0,0 L8,4 L0,8 Z\" fill=\"#FF512F\"/>\n    </marker>\n    <marker id=\"arrowGreen8\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"4\" orient=\"auto\">\n      <path d=\"M0,0 L8,4 L0,8 Z\" fill=\"#76FF03\"/>\n    </marker>\n  </defs>\n\n  <g transform=\"translate(20, 20)\">\n    <text x=\"182\" y=\"30\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"16.5\" font-weight=\"bold\">1. 3D Uniform Circular Path</text>\n    <ellipse cx=\"180\" cy=\"220\" rx=\"135\" ry=\"75\" fill=\"url(#circGrad8)\" stroke=\"#00E5FF\" stroke-width=\"2.5\"/>\n    <circle cx=\"180\" cy=\"220\" r=\"7\" fill=\"#FFFFFF\"/>\n    <text x=\"160\" y=\"245\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">Center O</text>\n\n    <line x1=\"180\" y1=\"220\" x2=\"180\" y2=\"70\" stroke=\"#AB47BC\" stroke-width=\"4\" stroke-dasharray=\"6,4\"/>\n    <text x=\"195\" y=\"80\" fill=\"#AB47BC\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">ω (Angular Speed)</text>\n\n    <circle cx=\"315\" cy=\"220\" r=\"14\" fill=\"#FFD700\" stroke=\"#FFFFFF\" stroke-width=\"2\" filter=\"url(#glowCirc8)\"/>\n    <text x=\"330\" y=\"225\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">Particle P</text>\n\n    <line x1=\"180\" y1=\"220\" x2=\"315\" y2=\"220\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n    <text x=\"235\" y=\"210\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">Radius r</text>\n\n    <line x1=\"315\" y1=\"220\" x2=\"315\" y2=\"100\" stroke=\"#76FF03\" stroke-width=\"4.5\" marker-end=\"url(#arrowGreen8)\"/>\n    <text x=\"325\" y=\"120\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">v</text>\n\n    <line x1=\"315\" y1=\"220\" x2=\"200\" y2=\"220\" stroke=\"#FF512F\" stroke-width=\"4.5\" marker-end=\"url(#arrowRed8)\"/>\n    <text x=\"220\" y=\"245\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">a_c (Centripetal)</text>\n  </g>\n\n  <g transform=\"translate(415, 20)\">\n    <rect x=\"0\" y=\"0\" width=\"360\" height=\"410\" rx=\"12\" fill=\"rgba(15,23,42,0.9)\" stroke=\"#8E2DE2\" stroke-width=\"1.8\"/>\n    <text x=\"180\" y=\"35\" text-anchor=\"middle\" fill=\"#8E2DE2\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">2. Circular Kinematics Laws</text>\n\n    <rect x=\"15\" y=\"60\" width=\"330\" height=\"75\" rx=\"8\" fill=\"rgba(0,229,255,0.1)\" stroke=\"#00E5FF\" stroke-width=\"1.2\"/>\n    <text x=\"165\" y=\"85\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">Linear vs Angular Velocity:</text>\n    <text x=\"165\" y=\"115\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"16\" font-weight=\"bold\">v = r ω &nbsp; (v = ω × r)</text>\n\n    <rect x=\"15\" y=\"150\" width=\"330\" height=\"85\" rx=\"8\" fill=\"rgba(255,81,47,0.1)\" stroke=\"#FF512F\" stroke-width=\"1.2\"/>\n    <text x=\"165\" y=\"175\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">Centripetal Acceleration (a_c):</text>\n    <text x=\"165\" y=\"210\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"16\" font-weight=\"bold\">a_c = v² / r = r ω² = v ω</text>\n\n    <rect x=\"15\" y=\"250\" width=\"330\" height=\"85\" rx=\"8\" fill=\"rgba(118,255,3,0.1)\" stroke=\"#76FF03\" stroke-width=\"1.2\"/>\n    <text x=\"165\" y=\"275\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">Centripetal Force (F_c):</text>\n    <text x=\"165\" y=\"310\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"16\" font-weight=\"bold\">F_c = m a_c = m v² / r</text>\n\n    <text x=\"180\" y=\"365\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"13.5\" font-weight=\"bold\">✓ Direction of a_c is ALWAYS inward toward center O!</text>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 12px; line-height: 1.5; font-weight: 500;\">\n      💡 3D Circular orbit plane illustrating tangential velocity v and centripetal acceleration a_c.\n    </div>\n  </div>\n\n  <!-- QUICK REVISION CHEAT SHEET -->\n  <div style=\"background: rgba(142, 45, 226, 0.05); border: 1.5px solid #8E2DE2; border-radius: 12px; padding: 16px; margin-top: 35px; margin-bottom: 15px;\">\n    <h2 class=\"text-center\" style=\"color: #8E2DE2; margin: 0 0 6px 0; font-size: 20px; font-weight: bold; text-align: center !important;\">⚡ Quick Revision Cheat Sheet</h2>\n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 10px; font-size: 14px;\">\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3.5px solid #8E2DE2; border-radius: 6px;\">\n        <b style='color: #8E2DE2; display: block; margin-bottom: 3px;'>• 1D Motion Equations:</b>\n        <span style=\"color: #FFFFFF; line-height: 1.6; display: block;\">v = u + a t &nbsp;|&nbsp; s = u t + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> a t<sup>2</sup><br>v<sup>2</sup> - u<sup>2</sup> = 2 a s</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3.5px solid #8E2DE2; border-radius: 6px;\">\n        <b style='color: #8E2DE2; display: block; margin-bottom: 3px;'>• Vector Products:</b>\n        <span style=\"color: #FFFFFF; line-height: 1.6; display: block;\">Dot Product: A · B = |A||B| cos θ<br>Cross Product: |A × B| = |A||B| sin θ</span>\n      </div>\n    </div>\n  </div>\n</div>\n";

export const c11Phy2HtmlSolutions = "\n<style>\n  p, li, div:not(.table-container):not(.table-responsive):not(.pt-scroll-wrapper):not(.mcq-option) {\n    text-align: justify !important;\n  }\n  h1, h2, h3, h4, h5, h6 { text-align: left; }\n  .text-center { text-align: center !important; }\n  .text-left { text-align: left !important; }\n</style>\n\n<div style=\"padding: 12px; color: #E0E0E0; text-align: justify; font-family: system-ui, -apple-system, sans-serif; line-height: 1.7; font-size: 16px;\">\n  \n  <div style=\"text-align: center; margin-bottom: 25px; border-bottom: 2px solid #8E2DE2; padding-bottom: 10px;\">\n    <h2 style=\"color: #8E2DE2; margin: 0; font-size: 22px; font-weight: bold; text-align: center !important;\">NCERT & Master Solutions Guide</h2>\n    <p style=\"color: #B0BEC5; margin: 5px 0 0 0; font-size: 15px; text-align: center !important;\">Unit II: Kinematics — 100 Master Practice Questions (Theoretical & Numerical)</p>\n  </div>\n<h3 style=\"color: #8E2DE2; border-left: 4px solid #8E2DE2; padding-left: 10px; margin-top: 25px;\">Part A: Multiple Choice Questions (Q1 - Q25)</h3>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q1: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">The slope of position-time (x-t) graph represents which physical quantity?<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Distance</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Velocity</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Acceleration</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Work done</div>\n  </div></div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #8E2DE2;\">b) Velocity</span></b><br>The slope of x-t graph v = dx/dt represents instantaneous velocity.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q2: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">The area under velocity-time (v-t) graph represents:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Acceleration</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Speed</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Displacement</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Force</div>\n  </div></div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #8E2DE2;\">c) Displacement</span></b><br>Area under v-t graph = ∫v dt = Displacement Δx.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q3: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Which of the following is a scalar quantity?<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Displacement</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Velocity</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Electric Current</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Acceleration</div>\n  </div></div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #8E2DE2;\">c) Electric Current</span></b><br>Electric current has direction but does not obey laws of vector addition; it is a scalar quantity.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q4: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">If position x = 3 t<sup>2</sup> + 2 t + 5 m, the velocity at t = 2 s is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) 10 m s<sup>-1</sup></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) 14 m s<sup>-1</sup></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) 16 m s<sup>-1</sup></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) 20 m s<sup>-1</sup></div>\n  </div></div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #8E2DE2;\">b) 14 m s<sup>-1</sup></span></b><br>v = dx/dt = 6 t + 2. At t = 2 s, v = 6(2) + 2 = 14 m s<sup>-1</sup>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q5: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A body dropped from height h reaches ground in time t given by:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) t = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">2 h</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">g</span>\n  </span></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) t = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">√h</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">√g</span>\n  </span></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) t = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">√(2 h)</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">√g</span>\n  </span></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) t = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">h<sup>2</sup></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2 g</span>\n  </span></div>\n  </div></div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #8E2DE2;\">c) t = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">√(2 h)</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">√g</span>\n  </span></span></b><br>From h = 1/2 g t<sup>2</sup>, t = √(2h / g).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q6: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">The angle of projection for maximum horizontal range of a projectile is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) 30°</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) 45°</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) 60°</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) 90°</div>\n  </div></div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #8E2DE2;\">b) 45°</span></b><br>R = (u<sup>2</sup> sin 2θ)/g. R is maximum when sin 2θ = 1 ⇒ 2θ = 90° ⇒ θ = 45°.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q7: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Two vectors A and B are perpendicular if their dot product A · B is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) |A||B|</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) 1</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) 0</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) -1</div>\n  </div></div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #8E2DE2;\">c) 0</span></b><br>A · B = |A||B| cos 90° = 0.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q8: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">The magnitude of cross product |A × B| of two vectors is maximum when angle θ is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) 0°</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) 45°</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) 90°</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) 180°</div>\n  </div></div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #8E2DE2;\">c) 90°</span></b><br>|A × B| = |A||B| sin θ, which is maximum at θ = 90° (sin 90° = 1).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q9: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">In uniform circular motion, which quantity remains CONSTANT?<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Velocity vector</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Acceleration vector</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Speed</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Displacement</div>\n  </div></div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #8E2DE2;\">c) Speed</span></b><br>Speed is the magnitude of velocity and remains constant in uniform circular motion, whereas direction of velocity continuously changes.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q10: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Centripetal acceleration of a particle in circular motion of radius r with speed v is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) v / r</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) v<sup>2</sup> / r</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) v r</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) v / r<sup>2</sup></div>\n  </div></div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #8E2DE2;\">b) v<sup>2</sup> / r</span></b><br>Centripetal acceleration a<sub>c</sub> = v<sup>2</sup> / r = r ω<sup>2</sup>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q11: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">The displacement of a particle in n-th second of uniformly accelerated motion is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) u + a (n - 1)</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) u + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">a</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> (2 n - 1)</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) u n + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> a n<sup>2</sup></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) a / 2 (n - 1)</div>\n  </div></div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #8E2DE2;\">b) u + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">a</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> (2 n - 1)</span></b><br>s<sub>n<sup>th</sup></sub> = s<sub>n</sub> - s<sub>n-1</sub> = u + (a/2)(2n - 1).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q12: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A car covers first half distance at speed v<sub>1</sub> and second half at v<sub>2</sub>. Average speed is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">v<sub>1</sub> + v<sub>2</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">2 v<sub>1</sub> v<sub>2</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">v<sub>1</sub> + v<sub>2</sub></span>\n  </span></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) √(v<sub>1</sub> v<sub>2</sub>)</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">v<sub>1</sub> v<sub>2</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">v<sub>1</sub> + v<sub>2</sub></span>\n  </span></div>\n  </div></div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #8E2DE2;\">b) <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">2 v<sub>1</sub> v<sub>2</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">v<sub>1</sub> + v<sub>2</sub></span>\n  </span></span></b><br>Harmonic mean of speeds for equal distance intervals: v<sub>avg</sub> = 2 v<sub>1</sub> v<sub>2</sub> / (v<sub>1</sub> + v<sub>2</sub>).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q13: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">What is the unit vector parallel to vector A = 3 î + 4 ĵ?<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">3 î + 4 ĵ</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">5</span>\n  </span></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">3 î + 4 ĵ</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">7</span>\n  </span></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) 3 î + 4 ĵ</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">î + ĵ</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">5</span>\n  </span></div>\n  </div></div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #8E2DE2;\">a) <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">3 î + 4 ĵ</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">5</span>\n  </span></span></b><br>|A| = √(3<sup>2</sup> + 4<sup>2</sup>) = 5. Unit vector â = A / |A| = (3î + 4ĵ) / 5.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q14: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">The horizontal velocity component of a projectile during flight:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Increases continuously</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Decreases continuously</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Remains constant</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Becomes zero at apex</div>\n  </div></div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #8E2DE2;\">c) Remains constant</span></b><br>Assuming no air resistance, no horizontal force acts on the projectile (a<sub>x</sub> = 0), so u<sub>x</sub> = u cos θ remains constant.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q15: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">At the highest point of projectile trajectory, the angle between velocity and acceleration is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) 0°</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) 45°</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) 90°</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) 180°</div>\n  </div></div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #8E2DE2;\">c) 90°</span></b><br>At apex, velocity is purely horizontal (u cos θ) and acceleration due to gravity is vertically downward (g), making an angle of 90°.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q16: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">If A = 2 î + 3 ĵ and B = î - 2 ĵ, then dot product A · B is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) 5</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) -4</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) -1</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) 8</div>\n  </div></div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #8E2DE2;\">b) -4</span></b><br>A · B = (2)(1) + (3)(-2) = 2 - 6 = -4.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q17: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">The resultant of two forces 6 N and 8 N acting at right angles (90°) is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) 14 N</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) 2 N</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) 10 N</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) 48 N</div>\n  </div></div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #8E2DE2;\">c) 10 N</span></b><br>R = √(6<sup>2</sup> + 8<sup>2</sup>) = √(36 + 64) = √100 = 10 N.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q18: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Which graph represents a body at rest?<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Line parallel to time axis on x-t graph</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Inclined line on x-t graph</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Parabola on x-t graph</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Line parallel to time axis on v-t graph</div>\n  </div></div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #8E2DE2;\">a) Line parallel to time axis on x-t graph</span></b><br>Position x remains constant over time t, giving a horizontal line slope = dx/dt = 0.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q19: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">The magnitude of displacement can be:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Greater than distance</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Equal to or less than distance</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Always zero</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Always negative</div>\n  </div></div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #8E2DE2;\">b) Equal to or less than distance</span></b><br>|Displacement| ≤ Distance. Equality holds only for straight-line motion without direction change.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q20: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Relation between linear velocity v and angular velocity ω is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) v = r / ω</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) v = r ω</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) ω = v r</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) v = r<sup>2</sup> ω</div>\n  </div></div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #8E2DE2;\">b) v = r ω</span></b><br>Linear velocity v = r ω.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q21: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">If a body travels with uniform acceleration, its velocity-time graph is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) A straight line inclined to time axis</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) A curve (parabola)</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) A circle</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) A line parallel to velocity axis</div>\n  </div></div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #8E2DE2;\">a) A straight line inclined to time axis</span></b><br>Uniform acceleration means constant dv/dt, giving a straight line with constant slope on v-t graph.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q22: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">The maximum height reached by a projectile launched with velocity u at angle θ is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">u<sup>2</sup> sin θ</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">g</span>\n  </span></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">u<sup>2</sup> sin<sup>2</sup> θ</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2 g</span>\n  </span></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">u<sup>2</sup> sin 2θ</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">g</span>\n  </span></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">u sin θ</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2 g</span>\n  </span></div>\n  </div></div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #8E2DE2;\">b) <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">u<sup>2</sup> sin<sup>2</sup> θ</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2 g</span>\n  </span></span></b><br>H<sub>max</sub> = (u<sup>2</sup> sin<sup>2</sup> θ) / (2 g).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q23: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Vector sum of î × ĵ is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) 0</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) 1</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) k̂</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) -k̂</div>\n  </div></div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #8E2DE2;\">c) k̂</span></b><br>By right-hand thumb rule, î × ĵ = k̂.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q24: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">If speed of a particle moving in a circle of radius 2 m is doubled, its centripetal acceleration becomes:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Doubled</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Halved</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) 4 times</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) 8 times</div>\n  </div></div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #8E2DE2;\">c) 4 times</span></b><br>a<sub>c</sub> = v<sup>2</sup>/r. If v becomes 2v, a<sub>c</sub>' = (2v)<sup>2</sup>/r = 4 (v<sup>2</sup>/r) = 4 a<sub>c</sub>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q25: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A ball thrown vertically upwards with 20 m s<sup>-1</sup> reaches maximum height in (take g = 10 m s<sup>-2</sup>):<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) 1 s</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) 2 s</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) 3 s</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) 4 s</div>\n  </div></div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #8E2DE2;\">b) 2 s</span></b><br>t = u/g = 20 / 10 = 2 s.\n    </div>\n  </div><h3 style=\"color: #8E2DE2; border-left: 4px solid #8E2DE2; padding-left: 10px; margin-top: 35px;\">Part B: Very Short Answer Questions (Q26 - Q55)</h3>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q26: Define Kinematics</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">What is kinematics in physics?</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Kinematics is the branch of classical mechanics that describes the motion of points, bodies, and systems without considering the forces that cause the motion.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q27: Define Frame of Reference</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Define a frame of reference.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      A frame of reference is a coordinate system (axes + clock) attached to an observer relative to which position, displacement, and velocity of an object are measured.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q28: Inertial vs Non-Inertial Frame</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Differentiate between inertial and non-inertial frames of reference.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      An inertial frame is non-accelerating where Newton's laws hold true. A non-inertial frame is accelerating or rotating relative to an inertial frame.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q29: Distance vs Displacement Definition</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Distinguish between distance and displacement in 1 sentence.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Distance is total path length traversed (scalar), whereas displacement is the shortest directed straight-line vector from initial to final position.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q30: Average Speed Formula</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Define average speed and state its mathematical expression.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Average speed is total distance divided by total time: Average Speed = Total Path Length / Total Time.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q31: Instantaneous Speed Definition</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">What is instantaneous speed?</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Instantaneous speed is the magnitude of instantaneous velocity at a specific instant of time: v = limit(Δt→0) [Δs / Δt] = ds / dt.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q32: Define Acceleration</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Define acceleration and state its SI unit.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Acceleration is the rate of change of velocity with respect to time: a = dv / dt. Its SI unit is m s<sup>-2</sup>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q33: Slope of x-t Graph</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">What physical quantity is given by the slope of position-time graph?</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      The slope of position-time graph (dx/dt) represents Instantaneous Velocity.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q34: Slope of v-t Graph</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">What physical quantity is given by the slope of velocity-time graph?</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      The slope of velocity-time graph (dv/dt) represents Instantaneous Acceleration.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q35: Area under v-t Graph</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">What physical quantity is represented by the area under a v-t graph?</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      The area under a velocity-time graph (∫v dt) represents total Displacement of the object.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q36: First Equation of Motion</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State the first equation of motion for uniform acceleration.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      First equation of motion: v = u + a t.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q37: Second Equation of Motion</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State the second equation of motion.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Second equation of motion: s = u t + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> a t<sup>2</sup>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q38: Third Equation of Motion</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State the third equation of motion.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Third equation of motion: v<sup>2</sup> - u<sup>2</sup> = 2 a s.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q39: Distance in n-th Second Formula</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State the formula for distance traveled in n-th second.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      s<sub>n<sup>th</sup></sub> = u + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">a</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> (2 n - 1).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q40: Define Scalar Quantity</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Define a scalar quantity with two examples.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      A scalar quantity is a physical quantity having magnitude only and no direction (e.g. Mass, Temperature, Distance).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q41: Define Vector Quantity</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Define a vector quantity with two examples.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      A vector quantity possesses both magnitude and direction, and obeys vector addition laws (e.g. Force, Velocity, Displacement).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q42: Define Unit Vector</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">What is a unit vector? State its formula.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      A unit vector is a vector of magnitude 1 pointing in a specified direction: â = A / |A|.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q43: Define Zero Vector</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">What is a zero or null vector?</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      A zero vector is a vector having zero magnitude and an arbitrary direction, represented as 0.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q44: Components of Vector in 2D</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Write rectangular components of a vector A making angle θ with x-axis.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      A<sub>x</sub> = |A| cos θ &nbsp;and&nbsp; A<sub>y</sub> = |A| sin θ.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q45: Magnitude of Vector A = Ax i + Ay j</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Write the formula for magnitude of vector A = A<sub>x</sub> î + A<sub>y</sub> ĵ.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      |A| = √(A<sub>x</sub><sup>2</sup> + A<sub>y</sub><sup>2</sup>).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q46: Scalar Product Definition</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Define scalar (dot) product of two vectors A and B.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Scalar product A · B = |A||B| cos θ, where θ is the angle between vectors.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q47: Vector Product Definition</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Define vector (cross) product of two vectors A and B.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Vector product A × B = |A||B| sin θ n̂, where n̂ is unit vector perpendicular to both A and B.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q48: Dot Product of Perpendicular Vectors</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">What is the value of dot product of two perpendicular vectors?</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      For perpendicular vectors (θ = 90°), A · B = 0.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q49: Cross Product of Parallel Vectors</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">What is the cross product of two parallel vectors?</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      For parallel vectors (θ = 0° or 180°), A × B = 0.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q50: Define Projectile Motion</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">What is projectile motion?</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Projectile motion is two-dimensional motion of a body launched into air with an initial velocity under uniform downward gravity.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q51: Time of Flight Formula</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State the formula for time of flight T of a projectile.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      T = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">2 u sin θ</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">g</span>\n  </span>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q52: Maximum Height Formula</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State the formula for maximum height H of a projectile.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      H = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">u<sup>2</sup> sin<sup>2</sup> θ</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2 g</span>\n  </span>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q53: Horizontal Range Formula</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State the formula for horizontal range R of a projectile.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      R = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">u<sup>2</sup> sin 2θ</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">g</span>\n  </span>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q54: Define Angular Velocity</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Define angular velocity ω in circular motion.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Angular velocity is the rate of change of angular displacement: ω = dθ / dt = 2π / T.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q55: Centripetal Acceleration Formula</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State the formula for centripetal acceleration.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      a<sub>c</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">v<sup>2</sup></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">r</span>\n  </span> = r ω<sup>2</sup>.\n    </div>\n  </div><h3 style=\"color: #8E2DE2; border-left: 4px solid #8E2DE2; padding-left: 10px; margin-top: 35px;\">Part C: Short Answer Questions (Q56 - Q85)</h3>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q56: Difference Between Speed and Velocity</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Differentiate between speed and velocity with 4 distinct comparison points.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      1. <b>Nature:</b> Speed is scalar; Velocity is vector.<br>2. <b>Direction:</b> Speed has no direction; Velocity includes direction.<br>3. <b>Sign:</b> Speed is always positive or zero; Velocity can be positive, negative, or zero.<br>4. <b>Formula:</b> Speed = Distance/Time; Velocity = Displacement/Time.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q57: Differentiation Method for v and a</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Position of particle x(t) = 4 t<sup>3</sup> - 2 t<sup>2</sup> + 5 m. Find velocity and acceleration at t = 2 s.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Velocity v = dx/dt = 12 t<sup>2</sup> - 4 t.<br>At t = 2 s: v = 12(4) - 4(2) = 48 - 8 = <b>40 m s<sup>-1</sup></b>.<br>Acceleration a = dv/dt = 24 t - 4.<br>At t = 2 s: a = 24(2) - 4 = 48 - 4 = <b>44 m s<sup>-2</sup></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q58: Integration Method for Displacement</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Velocity of a particle v(t) = 3 t<sup>2</sup> + 4 t m s<sup>-1</sup>. Find displacement between t = 1 s and t = 3 s.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Displacement Δx = ∫ v dt (from 1 to 3) = ∫ (3 t<sup>2</sup> + 4 t) dt = [t<sup>3</sup> + 2 t<sup>2</sup>]<sub>1</sub><sup>3</sup>.<br>At t = 3: 3<sup>3</sup> + 2(3)<sup>2</sup> = 27 + 18 = 45.<br>At t = 1: 1<sup>3</sup> + 2(1)<sup>2</sup> = 1 + 2 = 3.<br>Δx = 45 - 3 = <b>42 m</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q59: Derive s_nth Formula</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Derive formula for displacement in n-th second s<sub>n<sup>th</sup></sub> = u + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">a</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span>(2n - 1).</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Displacement in n seconds: s<sub>n</sub> = u n + 1/2 a n<sup>2</sup>.<br>Displacement in (n-1) seconds: s<sub>n-1</sub> = u(n-1) + 1/2 a(n-1)<sup>2</sup>.<br>s<sub>n<sup>th</sup></sub> = s<sub>n</sub> - s<sub>n-1</sub> = [u n + 1/2 a n<sup>2</sup>] - [u n - u + 1/2 a (n<sup>2</sup> - 2n + 1)].<br>s<sub>n<sup>th</sup></sub> = u + 1/2 a [n<sup>2</sup> - n<sup>2</sup> + 2n - 1] = <b>u + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">a</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span>(2n - 1)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q60: Car Stopping Distance Problem</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A car moving at 20 m s<sup>-1</sup> is stopped by applying brakes with uniform retardation of 4 m s<sup>-2</sup>. Find stopping distance and time.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Initial u = 20 m/s, final v = 0, acceleration a = -4 m/s<sup>2</sup>.<br>1. Time: v = u + a t ⇒ 0 = 20 - 4 t ⇒ <b>t = 5 s</b>.<br>2. Distance: v<sup>2</sup> - u<sup>2</sup> = 2 a s ⇒ 0 - 400 = 2(-4) s ⇒ -400 = -8 s ⇒ <b>s = 50 m</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q61: Parabolic Trajectory Proof</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Prove dimensionally/analytically that trajectory of a projectile is parabolic y = ax - bx<sup>2</sup>.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Horizontal motion: x = (u cos θ) t ⇒ t = x / (u cos θ).<br>Vertical motion: y = (u sin θ) t - 1/2 g t<sup>2</sup>.<br>Substitute t: y = (u sin θ) [x / (u cos θ)] - 1/2 g [x / (u cos θ)]<sup>2</sup>.<br><b>y = x tan θ - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">g x<sup>2</sup></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2 u<sup>2</sup> cos<sup>2</sup> θ</span>\n  </span></b>.<br>This equation is of form y = a x - b x<sup>2</sup>, which represents a parabola!\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q62: Triangle Law of Vector Addition</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State Triangle Law of Vector Addition with diagram specification.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      If two vectors are represented in magnitude and direction by two sides of a triangle taken in the same order, their resultant is represented in magnitude and direction by the third side taken in the reverse order.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q63: Parallelogram Law Resultant Formula</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Write resultant magnitude and direction formula for Parallelogram Law of Vector Addition.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Resultant Magnitude R = √(A<sup>2</sup> + B<sup>2</sup> + 2 A B cos θ).<br>Direction angle α with vector A: tan α = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">B sin θ</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">A + B cos θ</span>\n  </span>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q64: Magnitude and Unit Vector Problem</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Find magnitude and unit vector for A = 6 î + 8 ĵ.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Magnitude |A| = √(6<sup>2</sup> + 8<sup>2</sup>) = √(36 + 64) = √100 = <b>10</b>.<br>Unit vector â = A / |A| = <b><span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">6 î + 8 ĵ</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">10</span>\n  </span> = 0.6 î + 0.8 ĵ</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q65: Dot Product Problem for Work</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Force F = 3 î + 4 ĵ - 2 k̂ N displaces a body by s = 2 î + 5 ĵ + 3 k̂ m. Calculate work done.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Work W = F · s = (3)(2) + (4)(5) + (-2)(3) = 6 + 20 - 6 = <b>20 Joules</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q66: Angle Between Two Vectors Using Dot Product</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Find angle θ between vectors A = î + ĵ and B = ĵ + k̂.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      A · B = (1)(0) + (1)(1) + (0)(1) = 1.<br>|A| = √(1<sup>2</sup> + 1<sup>2</sup>) = √2, &nbsp;|B| = √(1<sup>2</sup> + 1<sup>2</sup>) = √2.<br>cos θ = (A · B) / (|A||B|) = 1 / (√2 × √2) = 1/2.<br>θ = cos<sup>-1</sup>(1/2) = <b>60°</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q67: Cross Product Magnitude Problem</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Find magnitude of cross product |A × B| for A = 2 î + 3 ĵ and B = 4 î - ĵ.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      A × B = (2 î + 3 ĵ) × (4 î - ĵ) = 2(4)(î×î) - 2(î×ĵ) + 12(ĵ×î) - 3(ĵ×ĵ).<br>Since î×î = ĵ×ĵ = 0, î×ĵ = k̂, ĵ×î = -k̂:<br>A × B = -2 k̂ - 12 k̂ = -14 k̂.<br>Magnitude |A × B| = <b>14</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q68: Complementary Projection Angles for Same Range</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Show that horizontal range of a projectile is same for two angles of projection θ and (90° - θ).</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Range at angle θ: R<sub>1</sub> = (u<sup>2</sup> sin 2θ)/g.<br>Range at angle (90° - θ): R<sub>2</sub> = [u<sup>2</sup> sin 2(90° - θ)] / g = [u<sup>2</sup> sin (180° - 2θ)] / g.<br>Since sin(180° - x) = sin x, R<sub>2</sub> = (u<sup>2</sup> sin 2θ)/g = R<sub>1</sub>.<br><b>Thus, range is identical for complementary angles θ and (90° - θ)!</b>\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q69: Projectile Launch Velocity Problem</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A projectile is launched with speed 30 m s<sup>-1</sup> at 30° to horizontal. Find Time of Flight (g = 10 m s<sup>-2</sup>).</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      T = (2 u sin θ) / g = [2(30) sin 30°] / 10 = [60 × 0.5] / 10 = <b>3 seconds</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q70: Projectile Range Calculation</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A shell is fired with velocity 100 m s<sup>-1</sup> at 45°. Calculate its horizontal range (g = 10 m s<sup>-2</sup>).</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      R = (u<sup>2</sup> sin 2θ) / g = [100<sup>2</sup> sin 90°] / 10 = 10000 / 10 = <b>1000 metres (1 km)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q71: Relation v = r ω Proof</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Derive relation between linear velocity v and angular velocity ω in circular motion.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Arc length s = r θ. Differentiating with respect to time t:<br>ds/dt = r (dθ/dt).<br>Since ds/dt = v (linear velocity) and dθ/dt = ω (angular velocity):<br><b>v = r ω</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q72: Centripetal Force Problem</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A 0.5 kg stone tied to a string of length 1 m is whirled in a horizontal circle at speed 4 m s<sup>-1</sup>. Find string tension.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Tension T = Centripetal Force F<sub>c</sub> = m v<sup>2</sup> / r.<br>F<sub>c</sub> = [0.5 × 4<sup>2</sup>] / 1 = [0.5 × 16] / 1 = <b>8 Newtons</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q73: Relative Velocity in 1D Definition</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Define relative velocity of body A with respect to body B in 1D motion.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Relative velocity v<sub>AB</sub> is the time rate of change of position of body A with respect to body B: v<sub>AB</sub> = v<sub>A</sub> - v<sub>B</sub>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q74: Relative Velocity Opposite Directions</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Two trains A and B of length 100 m travel in opposite directions at 20 m s<sup>-1</sup> and 30 m s<sup>-1</sup>. Find crossing time.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Relative speed v<sub>rel</sub> = v<sub>A</sub> + v<sub>B</sub> = 20 + 30 = 50 m s<sup>-1</sup>.<br>Total distance to clear each other = L<sub>1</sub> + L<sub>2</sub> = 100 + 100 = 200 m.<br>Time t = Distance / v<sub>rel</sub> = 200 / 50 = <b>4 seconds</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q75: Average Velocity in Equal Time Intervals</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A body travels at 10 m s<sup>-1</sup> for 2 s and then at 30 m s<sup>-1</sup> for 2 s. Find average velocity.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Equal time intervals: Average velocity = (v<sub>1</sub> + v<sub>2</sub>) / 2 = (10 + 30) / 2 = <b>20 m s<sup>-1</sup></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q76: Kinematic Graph Interpretation</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Explain the shape of x-t graph for (i) uniform positive velocity, (ii) uniform acceleration.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      (i) <b>Uniform Positive Velocity:</b> Straight line inclined to time axis with constant positive slope.<br>(ii) <b>Uniform Acceleration:</b> Parabola opening upwards with increasing slope.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q77: Null Vector Properties</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State three main properties of zero (null) vector 0.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      1. A + 0 = A<br>2. λ 0 = 0 (where λ is a scalar)<br>3. 0 · A = 0\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q78: Orthogonal Unit Vectors Dot Product</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Prove that î · î = 1 and î · ĵ = 0.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      1. î · î = |î||î| cos 0° = (1)(1)(1) = 1.<br>2. î · ĵ = |î||ĵ| cos 90° = (1)(1)(0) = 0.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q79: Right Hand Rule for Cross Product</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Explain Right-Hand Thumb Rule for determining direction of cross product A × B.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Curl the fingers of right hand from vector A towards vector B through smaller angle θ; the stretched thumb points in direction of cross product C = A × B.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q80: Apex Velocity of Projectile</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Why is velocity of projectile not zero at apex?</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      At apex, vertical velocity component becomes zero (v<sub>y</sub> = 0), but horizontal component u<sub>x</sub> = u cos θ remains active, so total velocity is u cos θ (non-zero).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q81: Rain Man Relative Velocity Concept</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Explain why a walking person must tilt their umbrella forward in vertical rain.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Relative velocity of rain with respect to man v<sub>RM</sub> = v<sub>R</sub> - v<sub>M</sub>. The resultant vector tilts forward at angle tan θ = v<sub>M</sub> / v<sub>R</sub>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q82: Centripetal vs Centrifugal Force</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Differentiate between centripetal force and centrifugal force.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Centripetal force is a real inward force acting toward center in inertial frame. Centrifugal force is a pseudo outward force observed in rotating non-inertial frame.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q83: Angular Acceleration Definition</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Define angular acceleration α and state its relation with linear acceleration a.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Angular acceleration is rate of change of angular velocity α = dω / dt (rad s<sup>-2</sup>). Relation: tangential acceleration a<sub>t</sub> = r α.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q84: Condition for Equal Range and Max Height</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">At what projection angle θ is horizontal range R equal to maximum height H?</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      R = H ⇒ (u<sup>2</sup> sin 2θ)/g = (u<sup>2</sup> sin<sup>2</sup> θ)/(2g) ⇒ 2 sin θ cos θ = sin<sup>2</sup> θ / 2 ⇒ tan θ = 4 ⇒ <b>θ = tan<sup>-1</sup>(4) ≈ 76°</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q85: Dimensional Proof of v² - u² = 2 a s</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Verify dimensional correctness of v<sup>2</sup> - u<sup>2</sup> = 2 a s.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      LHS: [v<sup>2</sup>] = [L<sup>2</sup> T<sup>-2</sup>].<br>RHS: [2 a s] = [1] × [L T<sup>-2</sup>] × [L] = [L<sup>2</sup> T<sup>-2</sup>].<br>LHS = RHS. Dimensionally correct!\n    </div>\n  </div><h3 style=\"color: #8E2DE2; border-left: 4px solid #8E2DE2; padding-left: 10px; margin-top: 35px;\">Part D: Long Answer Questions (Q86 - Q100)</h3>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q86: Graphical Derivation of 3 Equations of Motion</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Derive the three kinematic equations of motion (v = u + at, s = ut + 1/2 at<sup>2</sup>, v<sup>2</sup> - u<sup>2</sup> = 2as) for uniform acceleration using velocity-time graph.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Consider a body moving with uniform acceleration a, initial velocity u at t = 0, and final velocity v at time t.<br><br><b>(i) First Equation (v = u + a t):</b><br>Slope of v-t graph = Acceleration a = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">Change in Velocity</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">Time</span>\n  </span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">v - u</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">t</span>\n  </span>.<br>a t = v - u &nbsp; ⇒ &nbsp; <b>v = u + a t</b>.<br><br><b>(ii) Second Equation (s = u t + 1/2 a t<sup>2</sup>):</b><br>Displacement s = Area under v-t graph = Area of rectangle + Area of triangle.<br>s = (u × t) + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> × t × (v - u).<br>Substitute (v - u) = a t:<br>s = u t + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> × t × (a t) &nbsp; ⇒ &nbsp; <b>s = u t + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> a t<sup>2</sup></b>.<br><br><b>(iii) Third Equation (v<sup>2</sup> - u<sup>2</sup> = 2 a s):</b><br>Displacement s = Area of Trapezoid = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">(u + v)</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> × t.<br>From first equation t = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">v - u</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">a</span>\n  </span>. Substitute t:<br>s = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">(v + u)</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> × <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">(v - u)</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">a</span>\n  </span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">v<sup>2</sup> - u<sup>2</sup></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2 a</span>\n  </span>.<br><b>v<sup>2</sup> - u<sup>2</sup> = 2 a s</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q87: Complete Theory & Derivation of Projectile Motion</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Define projectile motion. Derive expressions for (i) Parabolic trajectory equation, (ii) Time of flight T, (iii) Maximum height H, and (iv) Horizontal range R.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Consider a projectile launched with velocity u at angle θ to horizontal.<br><br><b>(i) Trajectory Equation:</b><br>Horizontal displacement: x = (u cos θ) t ⇒ t = x / (u cos θ).<br>Vertical displacement: y = (u sin θ) t - 1/2 g t<sup>2</sup>.<br>Substitute t: <b>y = x tan θ - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">g x<sup>2</sup></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2 u<sup>2</sup> cos<sup>2</sup> θ</span>\n  </span></b> (Parabola).<br><br><b>(ii) Time of Flight T:</b><br>At return to ground y = 0: 0 = (u sin θ) T - 1/2 g T<sup>2</sup> ⇒ <b>T = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">2 u sin θ</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">g</span>\n  </span></b>.<br><br><b>(iii) Maximum Height H:</b><br>At highest point v<sub>y</sub> = 0: v<sub>y</sub><sup>2</sup> = u<sub>y</sub><sup>2</sup> - 2 g H ⇒ 0 = u<sup>2</sup> sin<sup>2</sup> θ - 2 g H ⇒ <b>H = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">u<sup>2</sup> sin<sup>2</sup> θ</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2 g</span>\n  </span></b>.<br><br><b>(iv) Horizontal Range R:</b><br>R = u<sub>x</sub> × T = (u cos θ) × <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">2 u sin θ</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">g</span>\n  </span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">u<sup>2</sup> (2 sin θ cos θ)</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">g</span>\n  </span> ⇒ <b>R = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">u<sup>2</sup> sin 2θ</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">g</span>\n  </span></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q88: Laws of Vector Addition & Derivation of Resultant</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State Parallelogram Law of Vector Addition. Derive mathematical expressions for magnitude R and direction α of the resultant of two vectors A and B at angle θ.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Parallelogram Law:</b> If two vectors acting simultaneously at a point are represented in magnitude and direction by two adjacent sides of a parallelogram, their resultant is represented by the diagonal passing through their common point.<br><br><b>Derivation:</b><br>Let vectors A along OA and B along OB make angle θ. Complete parallelogram OACB.<br>From C drop perpendicular CD to extended line OA.<br>In right triangle CDC': CD = B sin θ, &nbsp;AD = B cos θ.<br>Total base OD = OA + AD = A + B cos θ.<br>In right triangle ODC, by Pythagoras theorem:<br>OC<sup>2</sup> = OD<sup>2</sup> + CD<sup>2</sup> = (A + B cos θ)<sup>2</sup> + (B sin θ)<sup>2</sup>.<br>R<sup>2</sup> = A<sup>2</sup> + 2 A B cos θ + B<sup>2</sup> cos<sup>2</sup> θ + B<sup>2</sup> sin<sup>2</sup> θ = A<sup>2</sup> + B<sup>2</sup> + 2 A B cos θ.<br><b>R = √(A<sup>2</sup> + B<sup>2</sup> + 2 A B cos θ)</b>.<br><br><b>Direction α:</b><br>tan α = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">CD</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">OD</span>\n  </span> = <b><span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">B sin θ</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">A + B cos θ</span>\n  </span></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q89: Scalar Product (Dot Product) Complete Properties & Derivations</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Explain Scalar Product A · B in detail. Derive its component formula and list 5 fundamental properties with applications.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Definition:</b> A · B = |A||B| cos θ.<br><br><b>Component Formula Derivation:</b><br>Let A = A<sub>x</sub> î + A<sub>y</sub> ĵ + A<sub>z</sub> k̂ &nbsp;and&nbsp; B = B<sub>x</sub> î + B<sub>y</sub> ĵ + B<sub>z</sub> k̂.<br>Expanding dot product using î·î = ĵ·ĵ = k̂·k̂ = 1 and orthogonal dot products = 0:<br><b>A · B = A<sub>x</sub> B<sub>x</sub> + A<sub>y</sub> B<sub>y</sub> + A<sub>z</sub> B<sub>z</sub></b>.<br><br><b>Properties:</b><br>1. Commutative: A · B = B · A.<br>2. Perpendicular vectors: A · B = 0 (θ = 90°).<br>3. Self dot product: A · A = |A|<sup>2</sup>.<br>4. Angle formula: cos θ = (A · B) / (|A||B|).<br>5. Work Done: W = F · s.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q90: Vector Product (Cross Product) Complete Theory & Determinant Form</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Explain Vector Product A × B. State Right-Hand Thumb Rule, list 5 key properties, and show its evaluation using 3x3 determinant.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Definition:</b> A × B = |A||B| sin θ n̂.<br><br><b>Determinant Form:</b><br>A × B = | î &nbsp; ĵ &nbsp; k̂ |<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;| A<sub>x</sub> &nbsp; A<sub>y</sub> &nbsp; A<sub>z</sub> |<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;| B<sub>x</sub> &nbsp; B<sub>y</sub> &nbsp; B<sub>z</sub> |<br><b>A × B = (A<sub>y</sub> B<sub>z</sub> - A<sub>z</sub> B<sub>y</sub>) î - (A<sub>x</sub> B<sub>z</sub> - A<sub>z</sub> B<sub>x</sub>) ĵ + (A<sub>x</sub> B<sub>y</sub> - A<sub>y</sub> B<sub>x</sub>) k̂</b>.<br><br><b>Properties:</b><br>1. Anti-commutative: A × B = -(B × A).<br>2. Parallel vectors: A × B = 0.<br>3. Area of Parallelogram = |A × B|.<br>4. Area of Triangle = 1/2 |A × B|.<br>5. Torque τ = r × F.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q91: Derivation of Centripetal Acceleration in Circular Motion</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Derive expression for centripetal acceleration a<sub>c</sub> = v<sup>2</sup> / r = r ω<sup>2</sup> for uniform circular motion using vector calculus.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Consider a particle moving in circle of radius r with constant angular speed ω.<br>Position vector r(t) = r cos(ωt) î + r sin(ωt) ĵ.<br>Velocity vector v(t) = dr/dt = -r ω sin(ωt) î + r ω cos(ωt) ĵ.<br>Acceleration vector a(t) = dv/dt = -r ω<sup>2</sup> cos(ωt) î - r ω<sup>2</sup> sin(ωt) ĵ.<br>a(t) = -ω<sup>2</sup> [r cos(ωt) î + r sin(ωt) ĵ] = <b>-ω<sup>2</sup> r</b>.<br>The negative sign indicates acceleration is directed radially inward toward center.<br>Magnitude: <b>a<sub>c</sub> = ω<sup>2</sup> r = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">v<sup>2</sup></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">r</span>\n  </span></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q92: Relative Velocity in 2D (Rain-Man & River-Boat Problems)</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Explain Relative Velocity in 2D. Derive mathematical solutions for (i) Rain-Man problem, and (ii) River-Boat shortest path problem.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Relative Velocity:</b> v<sub>AB</sub> = v<sub>A</sub> - v<sub>B</sub>.<br><br><b>(i) Rain-Man Problem:</b><br>Rain falling vertically at v<sub>R</sub>, man walking horizontally at v<sub>M</sub>.<br>Relative velocity v<sub>RM</sub> = v<sub>R</sub> - v<sub>M</sub>.<br>Magnitude: <b>v<sub>RM</sub> = √(v<sub>R</sub><sup>2</sup> + v<sub>M</sub><sup>2</sup>)</b>.<br>Tilt angle of umbrella with vertical: <b>tan θ = v<sub>M</sub> / v<sub>R</sub></b>.<br><br><b>(ii) River-Boat Shortest Path:</b><br>To cross river of width d perpendicular to current v<sub>u</sub>, boat of speed v<sub>b</sub> must head upstream at angle θ:<br>sin θ = v<sub>u</sub> / v<sub>b</sub>.<br>Crossing time: <b>t = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">d</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">√(v<sub>b</sub><sup>2</sup> - v<sub>u</sub><sup>2</sup>)</span>\n  </span></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q93: Calculus Kinematics Master Problem</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Position of a particle along x-axis is x = t<sup>3</sup> - 6 t<sup>2</sup> + 9 t + 2 m. Find (i) initial velocity, (ii) time when particle comes to rest, (iii) acceleration at that instant.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Given:</b> x(t) = t<sup>3</sup> - 6 t<sup>2</sup> + 9 t + 2.<br>Velocity v(t) = dx/dt = 3 t<sup>2</sup> - 12 t + 9.<br>Acceleration a(t) = dv/dt = 6 t - 12.<br><br><b>(i) Initial Velocity (t = 0):</b> v(0) = 3(0) - 12(0) + 9 = <b>9 m s<sup>-1</sup></b>.<br><b>(ii) Time when at rest (v = 0):</b><br>3 t<sup>2</sup> - 12 t + 9 = 0 ⇒ t<sup>2</sup> - 4 t + 3 = 0 ⇒ (t - 1)(t - 3) = 0.<br>Particle comes to rest at <b>t = 1 s and t = 3 s</b>.<br><b>(iii) Acceleration at rest:</b><br>At t = 1 s: a(1) = 6(1) - 12 = <b>-6 m s<sup>-2</sup></b> (retardation).<br>At t = 3 s: a(3) = 6(3) - 12 = <b>+6 m s<sup>-2</sup></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q94: Master Numerical Problem on Projectile Motion</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A projectile is launched from ground with u = 40 m s<sup>-1</sup> at θ = 30° (g = 10 m s<sup>-2</sup>). Calculate (i) Time of flight, (ii) Maximum height, (iii) Horizontal range, (iv) Velocity vector after 1 s.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Initial components: u<sub>x</sub> = 40 cos 30° = 40 (√3/2) = 20√3 ≈ 34.64 m/s.<br>u<sub>y</sub> = 40 sin 30° = 40 (0.5) = 20 m/s.<br><br><b>(i) Time of Flight T:</b> T = 2 u<sub>y</sub> / g = 2(20) / 10 = <b>4 seconds</b>.<br><b>(ii) Maximum Height H:</b> H = u<sub>y</sub><sup>2</sup> / (2g) = 400 / 20 = <b>20 metres</b>.<br><b>(iii) Horizontal Range R:</b> R = u<sub>x</sub> × T = 20√3 × 4 = <b>80√3 ≈ 138.56 metres</b>.<br><b>(iv) Velocity after t = 1 s:</b><br>v<sub>x</sub> = u<sub>x</sub> = 20√3 m/s.<br>v<sub>y</sub> = u<sub>y</sub> - g t = 20 - 10(1) = 10 m/s.<br>Velocity vector: <b>v = 20√3 î + 10 ĵ m/s</b> &nbsp;(Magnitude: √(1200 + 100) = √1300 ≈ 36.05 m/s).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q95: Vector Resolution and Resultant Master Problem</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Three vectors A = 3 î + 2 ĵ, B = -î + 4 ĵ, C = 2 î - 6 ĵ act on a particle. Find (i) Resultant vector R, (ii) Magnitude |R|, (iii) Unit vector r̂.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>(i) Resultant R = A + B + C:</b><br>R = (3 - 1 + 2) î + (2 + 4 - 6) ĵ = <b>4 î + 0 ĵ = 4 î</b>.<br><b>(ii) Magnitude |R|:</b> |R| = √(4<sup>2</sup> + 0<sup>2</sup>) = <b>4 units</b>.<br><b>(iii) Unit Vector r̂:</b> r̂ = R / |R| = 4 î / 4 = <b>î</b> (along positive x-axis).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q96: Non-Uniform Acceleration & Kinematic Integration</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Acceleration of a particle moving along straight line is a(t) = 6 t - 2 m s<sup>-2</sup>. If initial position x(0) = 2 m and initial velocity v(0) = 3 m s<sup>-1</sup>, find position x at t = 3 s.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Velocity: v(t) = v(0) + ∫ a dt = 3 + ∫ (6 t - 2) dt = 3 t<sup>2</sup> - 2 t + 3.<br>Position: x(t) = x(0) + ∫ v dt = 2 + ∫ (3 t<sup>2</sup> - 2 t + 3) dt = t<sup>3</sup> - t<sup>2</sup> + 3 t + 2.<br>At t = 3 s:<br>x(3) = 3<sup>3</sup> - 3<sup>2</sup> + 3(3) + 2 = 27 - 9 + 9 + 2 = <b>29 metres</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q97: Horizontal Projectile from Top of Tower</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A ball is thrown horizontally at 15 m s<sup>-1</sup> from top of a tower of height 45 m (g = 10 m s<sup>-2</sup>). Find (i) Time to hit ground, (ii) Distance from foot of tower, (iii) Final striking speed.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Height h = 45 m, initial vertical velocity u<sub>y</sub> = 0, u<sub>x</sub> = 15 m/s.<br><br><b>(i) Time to hit ground:</b> h = 1/2 g t<sup>2</sup> ⇒ 45 = 5 t<sup>2</sup> ⇒ t<sup>2</sup> = 9 ⇒ <b>t = 3 seconds</b>.<br><b>(ii) Horizontal distance:</b> x = u<sub>x</sub> × t = 15 × 3 = <b>45 metres</b>.<br><b>(iii) Striking speed:</b> v<sub>x</sub> = 15 m/s, v<sub>y</sub> = g t = 10(3) = 30 m/s.<br>Striking speed v = √(v<sub>x</sub><sup>2</sup> + v<sub>y</sub><sup>2</sup>) = √(15<sup>2</sup> + 30<sup>2</sup>) = √(225 + 900) = √1125 ≈ <b>33.54 m s<sup>-1</sup></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q98: Area & Slope Analysis of Complex v-t Graph</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A train starts from rest, accelerates at 2 m s<sup>-2</sup> for 10 s, runs at constant speed for 20 s, and retards at 1 m s<sup>-2</sup> to stop. Calculate total distance traveled.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Phase 1 (Acceleration): u = 0, a = 2, t<sub>1</sub> = 10 s ⇒ Max speed v = a t<sub>1</sub> = 20 m/s.<br>Distance s<sub>1</sub> = 1/2 a t<sub>1</sub><sup>2</sup> = 1/2 (2)(100) = 100 m.<br>Phase 2 (Constant Speed): v = 20 m/s, t<sub>2</sub> = 20 s.<br>Distance s<sub>2</sub> = v × t<sub>2</sub> = 20 × 20 = 400 m.<br>Phase 3 (Retardation): v = 20 m/s, a = -1 m/s<sup>2</sup>, final v = 0 ⇒ t<sub>3</sub> = 20 / 1 = 20 s.<br>Distance s<sub>3</sub> = v<sup>2</sup> / (2 a) = 400 / 2 = 200 m.<br><br><b>Total Distance s = s<sub>1</sub> + s<sub>2</sub> + s<sub>3</sub> = 100 + 400 + 200 = 700 metres.</b>\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q99: Dot and Cross Product Combined Identity Proof</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Prove Lagrange's identity for vectors: |A × B|<sup>2</sup> + (A · B)<sup>2</sup> = |A|<sup>2</sup> |B|<sup>2</sup>.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      LHS = |A × B|<sup>2</sup> + (A · B)<sup>2</sup>.<br>Substitute vector definitions:<br>|A × B|<sup>2</sup> = (|A||B| sin θ)<sup>2</sup> = |A|<sup>2</sup> |B|<sup>2</sup> sin<sup>2</sup> θ.<br>(A · B)<sup>2</sup> = (|A||B| cos θ)<sup>2</sup> = |A|<sup>2</sup> |B|<sup>2</sup> cos<sup>2</sup> θ.<br>LHS = |A|<sup>2</sup> |B|<sup>2</sup> (sin<sup>2</sup> θ + cos<sup>2</sup> θ).<br>Since sin<sup>2</sup> θ + cos<sup>2</sup> θ = 1:<br><b>LHS = |A|<sup>2</sup> |B|<sup>2</sup> = RHS. Proved!</b>\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #8E2DE2; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q100: Master Problem on Uniform Circular Motion</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A cyclist rides around a circular track of radius 50 m at speed 10 m s<sup>-1</sup>. Calculate (i) Angular velocity ω, (ii) Centripetal acceleration a<sub>c</sub>, (iii) Angle of banking required for safe turn without friction.</div>\n    <div style=\"background: rgba(142, 45, 226, 0.05); border-left: 3.5px solid #8E2DE2; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #8E2DE2; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Radius r = 50 m, speed v = 10 m/s, g = 9.8 m s<sup>-2</sup>.<br><br><b>(i) Angular Velocity ω:</b> ω = v / r = 10 / 50 = <b>0.2 rad s<sup>-1</sup></b>.<br><b>(ii) Centripetal Acceleration a<sub>c</sub>:</b> a<sub>c</sub> = v<sup>2</sup> / r = 100 / 50 = <b>2 m s<sup>-2</sup></b>.<br><b>(iii) Angle of Banking θ:</b> tan θ = v<sup>2</sup> / (r g) = 100 / (50 × 9.8) = 100 / 490 ≈ 0.204.<br><b>θ = tan<sup>-1</sup>(0.204) ≈ 11.5°</b>.\n    </div>\n  </div></div>";




